DOC='Chapter_04_Heart_Failure_and_Cardiogenic_Shock'
R={'ESC2026':('ESC heart failure guideline, 2026','https://doi.org/10.1093/eurheartj/ehag100'),
   'ESCSUMMARY':('ESC official summary of HF guideline changes, 2026','https://www.escardio.org/news/press/press-releases/major-changes-made-to-the-esc-guidelines-on-heart-failure/'),
   'AHA2022':('AHA/ACC/HFSA heart failure guideline, 2022','https://doi.org/10.1161/CIR.0000000000001063')}
rows=[]
def S(h,main,*children):return h,[(main,list(children))]
def add(*a,**k):rows.append(Q(*a,**k))

add('Definition, classification and diagnosis','EF Classification Must Specify the Guideline Framework',
 'A patient has an established symptomatic HF syndrome and reproducible LVEF of 46%. There is no previous lower EF measurement. How is this phenotype classified under the ESC 2026 HF guideline?',
 'Heart failure with reduced ejection fraction',[
 ('Heart failure with mildly reduced ejection fraction','This is the 41%–49% category in the AHA 2022 and older ESC frameworks. ESC 2026 removed that separate phenotype and includes this EF within reduced-EF HF.'),
 ('Heart failure with preserved ejection fraction','ESC 2026 retains preserved EF at 50% or more; 46% does not meet that numerical boundary, even though it may be described informally as only mildly impaired.'),
 ('Heart failure with improved ejection fraction','Improved EF requires a documented prior reduced value and a subsequent rise under the applicable definition. A single EF of 46% does not demonstrate an improving trajectory.')],
 [S('Guideline-Specific Phenotypes','**ESC 2026 defines reduced-EF HF using LVEF below 50% and preserved-EF HF using LVEF at least 50%.** The previous separate mildly reduced group is incorporated into reduced-EF HF.',
    'The AHA/ACC/HFSA 2022 framework instead labels EF ≤40% as reduced, 41%–49% as mildly reduced and ≥50% as preserved. Naming the framework prevents two defensible labels from competing in an undated question.',
    'EF classification is applied after establishing the clinical syndrome. A low measurement alone does not establish current symptomatic HF.'),
  S('Phenotype Is Different From Treatment Eligibility','**A changed phenotype boundary does not rewrite the eligibility criteria of every historical trial or device recommendation.** Preserve the actual EF thresholds and clinical conditions attached to each therapy.',
    'Review symptom burden, congestion, etiology, renal function, rhythm and the EF trajectory. Measurement variability matters near a boundary, particularly when the result would alter a consequential decision.',
    'Do not infer improved EF without a baseline or describe a patient as cured from a reassuring single scan. Document both the measured value and the guideline used so a classification update does not create ambiguity in the clinical record.')],['ESC2026','ESCSUMMARY','AHA2022'],style='direct')

add('Definition, classification and diagnosis','Improved EF Describes a Trajectory Rather Than Cure',
 'A patient previously treated for symptomatic dilated cardiomyopathy had LVEF 28%. After treatment, LVEF is 52% and symptoms have resolved. Under AHA/ACC/HFSA 2022 terminology, which classification best preserves the clinical history?',
 'Heart failure with improved ejection fraction',[
 ('Newly diagnosed HF with preserved EF','The current EF is preserved numerically, but this label loses the documented reduced-EF trajectory. HFimpEF identifies improvement from the previous reduced value.'),
 ('Pre-HF without a history of symptomatic HF','Pre-HF describes patients without current or prior HF symptoms/signs who have relevant structural or biomarker abnormalities; it does not erase an established previous symptomatic syndrome.'),
 ('Persistently reduced-EF HF under the AHA 2022 EF boundary','The current EF exceeds the AHA reduced-EF boundary. Persisting disease risk justifies continued care, but does not make the current EF remain 28% or negate the improved-EF category.')],
 [S('Apply the Named Definition','**AHA/ACC/HFSA 2022 defines HFimpEF as previous LVEF ≤40% with a subsequent measurement above 40%.** This patient meets both the baseline and follow-up conditions.',
    'The definition does not require the follow-up EF to exceed 50%, although it does here. Other consensus definitions may include an absolute improvement requirement, so do not silently merge definitions.',
    'A single preserved-EF measurement without a prior reduced value would not establish this trajectory.'),
  S('Continue Longitudinal Care','**Improved EF indicates treatment response or remission, not proof that the substrate and relapse risk have disappeared.** Continue indicated HF therapy even when symptoms resolve, unless a specific contraindication requires adjustment.',
    'Review etiology, rhythm, ventricular dimensions, treatment tolerance and recurrent symptoms. Reassess imaging when clinically indicated rather than stopping follow-up after one favorable result.',
    'Counsel against unsupervised withdrawal of medicines. Decisions about an existing device, arrhythmic risk or future pregnancy require their own assessment and cannot be settled by this classification alone. Documenting the earlier EF also helps avoid inappropriate transfer into a de novo HFpEF treatment pathway that disregards why ventricular function improved.')],['AHA2022'])

R['ESC2021']=('ESC heart failure guideline, 2021: conventional diagnostic thresholds','https://doi.org/10.1093/eurheartj/ehab368')

add('Definition, classification and diagnosis','Asymptomatic Structural Disease Is Pre-Heart Failure',
 'An adult with hypertension has never experienced HF symptoms or signs. Echocardiography reproducibly shows LV dilation and LVEF 35%. Under AHA/ACC/HFSA 2022 staging, which category applies?',
 'Stage B: pre-heart failure',[
 ('Stage A: at risk for heart failure','Stage A covers risk factors without structural or functional disease or qualifying biomarker abnormalities. Demonstrated LV dilation and systolic dysfunction move this patient beyond risk alone.'),
 ('Stage C: symptomatic heart failure','Stage C requires current or previous HF symptoms/signs with structural disease. Reduced EF is important but does not supply a symptom history that the vignette explicitly excludes.'),
 ('Stage D: advanced heart failure','Stage D concerns advanced, difficult-to-control symptomatic disease despite treatment. A low EF alone does not establish refractory symptoms or an advanced-HF trajectory.')],
 [S('Separate Stage From EF and Functional Class','**HF stage incorporates disease evolution and symptom history.** Stage B identifies an opportunity to prevent progression before a symptomatic syndrome develops.',
    'Structural abnormalities, impaired ventricular systolic function or evidence of increased filling pressure can establish pre-HF when symptoms/signs are absent. At-risk patients with qualifying persistent biomarker elevation can also meet the framework after competing causes are excluded.',
    'NYHA class describes functional limitation in established symptomatic HF and is not a substitute for the stage A–D framework. An EF category alone also does not determine stage.'),
  S('Act on the Underlying Abnormality','**Asymptomatic LV systolic dysfunction requires etiological evaluation and preventive treatment rather than reassurance from the absence of dyspnea.** Assess ischemia when appropriate, valve disease, cardiotoxic exposure, rhythm and familial disease.',
    'The AHA 2022 framework recommends ACE inhibition and evidence-based beta blockade in appropriate patients with LVEF ≤40% to prevent symptomatic HF; prior MI creates additional secondary-prevention considerations.',
    'Control blood pressure, review harmful drugs and arrange follow-up of function and symptoms. Do not apply every symptomatic-HFrEF trial regimen indiscriminately to all stage-B phenotypes. Conversely, a patient with previous symptomatic HF who improves on treatment does not revert to never-symptomatic pre-HF solely because today’s examination is normal.')],['AHA2022'])

add('Definition, classification and diagnosis','A Low Natriuretic Peptide Does Not Override High Clinical Suspicion',
 'An adult with BMI 42 kg/m² presents with abrupt severe dyspnea and orthopnea. NT-proBNP is 240 pg/mL and lung ultrasound shows diffuse bilateral B-lines. Respiratory stabilization is underway. Which investigation best resolves the discordance between the peptide result and suspected cardiac congestion?',
 'Prompt echocardiography integrated with the bedside assessment',[
 ('Repeat NT-proBNP after six hours before selecting cardiac imaging','Serial peptides may provide context, but obesity and abrupt pulmonary edema can lower concentrations. Repeating the same biomarker should not postpone imaging when clinical suspicion remains substantial.'),
 ('High-resolution chest CT as the next definitive test','Chest CT can characterize interstitial lung disease or another pulmonary abnormality when that phenotype is suspected. Abrupt orthopnea and B-lines with an unreliable exclusion biomarker first warrant direct cardiac structural and functional assessment.'),
 ('Spirometry with bronchodilator testing after oxygenation improves','Spirometry helps evaluate chronic obstructive airflow disease when the history and examination support it. It does not promptly resolve an acute cardiac-congestion question and can be difficult to interpret during decompensation.')],
 [S('Use the Correct Setting and Test','**Natriuretic peptides support probability assessment; they do not replace clinical evaluation.** NT-proBNP below 300 pg/mL is a conventional non-age-adjusted rule-out threshold in acute/decompensated presentations.',
    'Obesity can reduce concentrations. Flash pulmonary edema and selected right-sided or advanced presentations can also have unexpectedly low values, so a low result should not end evaluation when suspicion remains high.',
    'Age, AF and kidney dysfunction can increase values without proving left-sided HF. Bilateral B-lines indicate an interstitial syndrome but are not themselves uniquely cardiogenic.'),
  S('Reconcile the Discordant Findings','**Assess oxygenation, perfusion, examination and focused imaging promptly.** Echocardiography evaluates ventricular function, valve lesions and filling-pressure evidence while alternative pulmonary causes are considered.',
    'For reference, ESC 2021 conventional nonacute rule-out values were NT-proBNP <125 pg/mL or BNP <35 pg/mL; acute values were NT-proBNP <300 pg/mL or BNP <100 pg/mL. These are different clinical pathways, not interchangeable confirmation thresholds.',
    'ESC 2026 also discusses suggested age-adjusted outpatient NT-proBNP levels above which HF is likely: 125 pg/mL in younger adults under 50, 250 pg/mL at ages 50–75 years and 500 pg/mL in older adults over 75. These outpatient likelihood thresholds are not the acute rule-out pathway and do not independently confirm HF. Do not delay necessary respiratory support while resolving a discordant biomarker result.')],['ESC2021','ESC2026','AHA2022'])

R['HFAPEFF']=('HFA–PEFF diagnostic consensus, 2019','https://doi.org/10.1093/eurheartj/ehz641')
R['H2FPEF']=('Original H2FPEF derivation and validation study, 2018','https://doi.org/10.1161/CIRCULATIONAHA.118.034646')

add('Definition, classification and diagnosis','Exercise Filling Pressure Can Establish HFpEF Despite Normal Resting Pressure',
 'A patient with unexplained exertional dyspnea has LVEF 62%, no important valve disease and normal pulmonary function testing. Expert supine exercise catheterization reproduces symptoms. Which PAWP pattern meets the invasive HFpEF criterion in the original HFA–PEFF framework?',
 'Rest 11 mmHg; peak exercise 29 mmHg',[
 ('Rest 11 mmHg; peak exercise 23 mmHg','The resting value is below 15 mmHg and the supine exercise value is below 25 mmHg. This pair does not meet the cited absolute-pressure criterion, although a full physiological assessment may still identify other abnormalities.'),
 ('Rest 14 mmHg; peak exercise 24 mmHg','Both values are close to the relevant boundaries but remain below them. Borderline findings require attention to technique and the full clinical context rather than rounding measurements upward to force a diagnosis.'),
 ('Rest 10 mmHg; peak exercise 20 mmHg','Exercise normally increases flow and can raise filling pressure. This pattern remains below the original supine exercise threshold and does not independently establish HFpEF by that criterion.')],
 [S('Demonstrate the Physiological Abnormality','**HFpEF requires a compatible syndrome with objective evidence of abnormal cardiac filling pressures or associated structural/functional abnormalities.** Normal resting pressures do not exclude an exercise-limited phenotype.',
    'The HFA–PEFF framework uses resting PAWP ≥15 mmHg or LVEDP ≥16 mmHg as invasive evidence. In the specified supine exercise setting, peak PAWP ≥25 mmHg supports the diagnosis.',
    'The correct option’s 29-mmHg exercise value crosses that threshold while the resting value remains below 15 mmHg. Interpret a properly acquired result in the context of reproduced symptoms and alternative causes rather than as an isolated number.'),
  S('Acquisition and Interpretation Limits','**Body position, respiratory pressure swings, workload and measurement technique affect invasive exercise interpretation.** Confirm catheter position, waveform validity and a representative wedge recording.',
    'Do not transfer a supine peak-pressure threshold indiscriminately to every upright protocol. Pressure–flow relationships and the overall hemodynamic pattern can provide additional information in specialist assessment.',
    'Review ischemia, pericardial disease, pulmonary pathology and chronotropic limitation when clinically relevant. Establishing HFpEF should lead to phenotype-directed management and comorbidity assessment, rather than stopping at a normal EF label. Conversely, an elevated wedge does not establish a specific myocardial etiology or mean every dyspneic patient needs invasive testing; use it when noninvasive evaluation leaves consequential uncertainty.')],['HFAPEFF','AHA2022'])

add('Definition, classification and diagnosis','H2FPEF Estimates Probability Rather Than Replacing Clinical Assessment',
 'An ambulatory patient with unexplained exertional dyspnea and preserved EF has a correctly calculated H2FPEF score of 8. There is no important valve lesion. What does this score most appropriately indicate?',
 'A high estimated probability of HFpEF that should be integrated with the clinical and cardiac assessment',[
 ('An intermediate probability in the original diagnostic framework','The original score classifies 2–5 as intermediate and 6–9 as high probability. A score of eight therefore belongs to the high group, even though further testing may still be appropriate if findings are discordant.'),
 ('A high predicted risk of developing HFpEF over the next five years','The score estimates whether HFpEF currently explains otherwise unexplained dyspnea. It is not a prospective five-year incidence model, although several components also contribute to future cardiovascular risk.'),
 ('Invasive confirmation of HFpEF equivalent to an abnormal exercise wedge pressure','The score was derived against invasive physiological assessment but does not itself measure filling pressures. A high estimated probability is not interchangeable with a technically valid invasive confirmation in a patient with consequential residual uncertainty.')],
 [S('Understand the Derivation Question','**H2FPEF combines six clinical and echocardiographic predictors to estimate HFpEF likelihood in patients with unexplained dyspnea.** The original study used invasive exercise assessment to distinguish HFpEF from noncardiac dyspnea.',
    'AF contributes three points and obesity two; the remaining four variables contribute one each. The total ranges from zero to nine.',
    'A high score is useful evidence but does not exclude an alternative or concurrent explanation for symptoms. Its calibration depends on the population in which it is applied.'),
  S('Use Probability to Guide Evaluation','**Scores of 0–1 suggest low probability, 2–5 intermediate probability and 6–9 high probability in the original framework.** Intermediate or discordant presentations often need additional functional assessment.',
    'Do not confuse this score with HFA–PEFF, which uses different domains, point assignment and decision boundaries. A high H2FPEF value does not automatically imply a high score in the other system.',
    'Check that each component was measured correctly, especially estimated PASP and E/e′. Obesity and AF strongly influence the result and can themselves contribute to disability. Combine probability with symptoms, imaging, laboratory findings and alternative-diagnosis assessment; use targeted functional or invasive testing when residual uncertainty would change treatment.')],['H2FPEF'],
 table=(['H2FPEF component','Original criterion','Points'],[
 ['Heavy','BMI >30 kg/m²','2'],['Hypertensive','Treatment with ≥2 antihypertensives','1'],['AF','Paroxysmal or persistent AF','3'],['Pulmonary hypertension','Echo-estimated PASP >35 mmHg','1'],['Elder','Age >60 years','1'],['Filling pressure','E/e′ >9','1']]))

add('Definition, classification and diagnosis','Intermediate HFA–PEFF Results Require Functional Assessment',
 'A patient has persistent exertional dyspnea, LVEF 60% and no significant valve disease or convincing alternative explanation. A correctly calculated resting HFA–PEFF score is 3. What is the next step in the original HFA–PEFF algorithm?',
 'Functional assessment with exercise echocardiography or appropriately selected invasive exercise hemodynamics',[
 ('Cardiac MRI for etiological characterization before functional confirmation','CMR can identify a specific cardiomyopathic or infiltrative cause, particularly with suggestive imaging or clinical findings. At the intermediate HFA–PEFF step, the unresolved issue is exercise-related filling-pressure abnormality; etiological characterization follows or accompanies confirmation as indicated.'),
 ('Resting right-heart catheterization without an exercise component','Elevated resting filling pressure can confirm a hemodynamic abnormality, but a normal resting result may miss exertional HFpEF. The functional step should address the exercise-limited presentation rather than stop at resting measurements alone.'),
 ('Repeat resting natriuretic peptide and echocardiography after three months','Repeat resting assessment may suit surveillance or a temporarily confounded initial study. Here the resting score is correctly measured and intermediate, so the algorithm calls for functional assessment rather than simply repeating the same resting evidence.')],
 [S('Three Domains With Limited Contributions','**The original HFA–PEFF echocardiographic/biomarker step combines functional, morphological and natriuretic-peptide domains.** A major criterion contributes two points and a minor criterion one.',
    'Each domain contributes at most two points, even when several criteria in that domain are positive. The resting score therefore ranges from zero to six.',
    'A total of at least five supports HFpEF, zero to one makes it unlikely, and two to four requires further assessment. Use the appropriate rhythm-specific biomarker criteria rather than treating AF and sinus rhythm identically.'),
  S('Resolve Exercise-Related Uncertainty','**Step F1 examines whether exertion produces pathological filling-pressure behavior.** Exercise echocardiography can assess the diastolic response when acquisition is adequate.',
    'If noninvasive exercise assessment is inconclusive, technically unsuitable or discordant with the clinical presentation, invasive exercise hemodynamics can clarify the diagnosis at an experienced center.',
    'Do not regard a normal resting EF or a nondiagnostic resting peptide as proof of normal exercise physiology. Conversely, an intermediate score should not automatically trigger invasive testing in every patient without considering test feasibility, alternative causes and whether the result would change care. After establishing the syndrome, investigate its etiology and relevant comorbidities rather than treating a positive score as the complete diagnosis.')],['HFAPEFF'],
 table=(['HFA–PEFF domain','Major: 2 points','Minor: 1 point'],[
 ['Functional','Age <75: septal e′ <7 or lateral e′ <10 cm/s; age ≥75: <5 or <7 respectively; OR mean E/e′ ≥15; OR TR velocity >2.8 m/s','Mean E/e′ 9–14 OR absolute GLS <16%'],
 ['Morphological','LAVI >34 mL/m² in sinus rhythm or >40 in AF; OR LVMI ≥149 (men)/122 (women) g/m² AND RWT >0.42','LAVI 29–34 in sinus rhythm or 34–40 in AF; OR LVMI >115 (men)/95 (women) g/m²; OR RWT >0.42; OR LV wall ≥12 mm'],
 ['Biomarker: sinus rhythm','NT-proBNP >220 OR BNP >80 pg/mL','NT-proBNP 125–220 OR BNP 35–80 pg/mL'],
 ['Biomarker: AF','NT-proBNP >660 OR BNP >240 pg/mL','NT-proBNP 375–660 OR BNP 105–240 pg/mL'],
 ['Total: maximum 2/domain','5–6: HFpEF supported; 0–1: unlikely','2–4: functional testing; do not add major and minor within one domain']]))

add('Definition, classification and diagnosis','Investigate the Cause of Newly Identified LV Dysfunction',
 'A stable patient has newly recognized global LV systolic dysfunction with EF 30%. Coronary evaluation shows no obstructive disease, echocardiography excludes important valve disease and routine laboratory testing is unrevealing. There is no shock, sustained ventricular arrhythmia or high-grade AV block. Which next investigation most usefully characterizes the myocardial substrate?',
 'Cardiac MRI with appropriate tissue-characterization sequences',[
 ('Endomyocardial biopsy as the next investigation before noninvasive tissue assessment','Biopsy is valuable when a suspected histological diagnosis would change treatment, particularly selected high-risk or progressive presentations. The stable scenario does not establish a reason to bypass noninvasive characterization for routine sampling.'),
 ('Cardiac FDG-PET with inflammation-directed preparation','FDG-PET can assess active inflammation in selected suspected cardiac sarcoidosis and help monitor treatment. Without a specific inflammatory phenotype, CMR offers broader initial myocardial characterization rather than immediately selecting a targeted metabolic investigation.'),
 ('A broad cardiomyopathy genetic panel as the initial substrate investigation','Genetic testing is valuable with an inherited phenotype, family history or when genotype changes counseling and management. It complements clinical and imaging phenotyping; in this uncharacterized sporadic presentation, it does not replace initial myocardial tissue imaging.')],
 [S('A Syndrome Label Does Not Identify Its Cause','**Reduced EF describes ventricular dysfunction but does not establish etiology.** The initial assessment should include history, examination, ECG, echo, relevant laboratory studies and a proportionate ischemic evaluation.',
    'Review cardiotoxic drugs, alcohol, persistent tachyarrhythmia, pregnancy-related timing, endocrine/metabolic disease and family history. A three-generation pedigree and genetic assessment may be appropriate when inherited cardiomyopathy is suspected.',
    'Treat congestion and initiate indicated HF care while investigation proceeds. An etiological workup is not a reason to leave a stable patient untreated.'),
  S('Choose a Test That Can Change Management','**CMR combines ventricular quantification with scar, edema and other tissue assessment.** Patterns can support ischemic injury, inflammation, infiltrative disease or another cardiomyopathic substrate.',
    'A CMR pattern is not infallible proof of a specific histology. Image quality, timing, contraindications and the clinical presentation influence its diagnostic value.',
    'Reserve endomyocardial biopsy for selected situations in which histology can alter treatment, weighing sampling limitations and procedural risks. Rapid deterioration, malignant arrhythmia or conduction disease can change the urgency and choice of investigation. Avoid applying either routine biopsy or routine invasive hemodynamic monitoring to every new low EF; select the investigation that answers the unresolved consequential question.')],['AHA2022','ESC2021'])

R['ACC2024']=('ACC HFrEF treatment consensus pathway, 2024','https://doi.org/10.1016/j.jacc.2023.12.024')
R['ARNILABEL']=('FDA Entresto prescribing information, 2024','https://www.accessdata.fda.gov/drugsatfda_docs/label/2024/218591Orig1s000%2C207620Orig1s025lbl.pdf')

add('Foundational treatment and safe prescribing','Establish Complementary Therapies Before Prolonged Single-Drug Titration',
 'A newly diagnosed patient with symptomatic HF and EF 28% is now euvolemic, warm and stable, with BP 122/76 mmHg, eGFR 62 mL/min/1.73 m² and potassium 4.3 mmol/L. No major contraindication to the four foundational classes is identified. Which initiation strategy best matches the ACC 2024 pathway?',
 'Introduce the complementary foundational classes promptly at tolerated doses, with monitoring and subsequent titration',[
 ('Introduce ARNI and beta blocker, then add MRA and SGLT2 therapy after target doses are reached','This traditional sequential approach may be needed when tolerance or monitoring constrains treatment. In the eligible stable patient supplied, waiting for target doses unnecessarily postpones the complementary benefits of the other classes.'),
 ('Introduce ARNI, MRA and SGLT2 therapy, deferring beta blockade until the three-month EF review','Deferring beta blockade is appropriate during unresolved hypoperfusion or active instability. This patient is compensated and warm; the later EF reassessment is not a prerequisite for beginning an indicated evidence-based beta blocker.'),
 ('Introduce ARNI, beta blocker and SGLT2 therapy, reserving MRA for persistent NYHA III symptoms','MRA treatment is not limited to NYHA III residual symptoms in otherwise eligible reduced-EF HF. The supplied kidney function and potassium do not provide a reason to omit it while waiting for greater symptom severity.')],
 [S('Complementary Treatment Effects','**The ACC 2024 HFrEF core regimen comprises an ARNI, an evidence-based beta blocker, an MRA and an SGLT2 inhibitor.** Use an appropriate renin–angiotensin alternative when ARNI cannot be used.',
    'No single mandatory sequence applies to every patient. Hemodynamics, congestion, kidney function, potassium, rhythm and contraindications guide initiation.',
    'Starting tolerated doses across the indicated classes is generally preferable to spending months maximizing only one or two. Aim for target or maximally tolerated doses as soon as feasible, ideally within three months under this pathway.'),
  S('Stabilization and Monitoring','**Rapid initiation means planned, monitored treatment rather than starting every medicine regardless of clinical state.** Initiate and increase beta blockade after compensation, not during hypoperfusion or escalating decompensation.',
    'Review blood pressure, pulse, weight, symptoms, renal function and electrolytes after changes. MRA and SGLT2 therapy often have less pressure-lowering effect than other components, which can inform an individualized sequence.',
    'Reassess loop requirements as congestion improves. Explain the purpose of each medicine and arrange early follow-up to address adherence and tolerability. A modest renal change does not automatically require stopping all prognostic treatment; interpret its magnitude, trajectory, volume status and competing causes. Record a specific contraindication when a class is omitted rather than allowing an incomplete regimen to persist without reassessment.')],['ACC2024','AHA2022'])

add('Foundational treatment and safe prescribing','ACE Inhibitor Washout Before Sacubitril/Valsartan',
 'A stable patient with symptomatic HF and EF 30% takes enalapril. The clinician plans to replace it with sacubitril/valsartan. There is no history of angioedema. Which transition is required?',
 'Stop enalapril and allow at least thirty-six hours before the first sacubitril/valsartan dose',[
 ('Stop enalapril and begin sacubitril/valsartan twelve hours later','A twelve-hour interval does not meet the required ACE inhibitor washout; concurrent effects on vasoactive peptide breakdown increase angioedema risk.'),
 ('Stop enalapril and begin sacubitril/valsartan twenty-four hours later','A one-day interruption remains shorter than the specified thirty-six-hour minimum. The usual dosing interval of the ACE inhibitor does not define an adequate washout.'),
 ('Overlap reduced-dose enalapril with sacubitril/valsartan during initial titration','Concomitant ACE inhibition and sacubitril/valsartan is contraindicated. Lowering either dose does not create a validated overlap strategy or remove the angioedema hazard.')],
 [S('Mechanism and Required Separation','**Sacubitril inhibits neprilysin while valsartan blocks the angiotensin II type-1 receptor.** Neprilysin inhibition augments endogenous vasoactive peptides; combining it with ACE inhibition increases angioedema risk.',
    'Allow at least 36 hours when switching from an ACE inhibitor to sacubitril/valsartan, and also before starting an ACE inhibitor after stopping sacubitril/valsartan.',
    'An ARB-to-ARNI transition does not require the same ACE-specific washout, but the prior ARB must be stopped because the combination already contains valsartan.'),
  S('Contraindications and Follow-Up','**A prior episode of ACE inhibitor- or ARB-related angioedema is a contraindication to sacubitril/valsartan.** A longer washout does not make that history irrelevant.',
    'Review pregnancy, blood pressure, renal function, potassium and interacting medicines before prescribing. Avoid duplicating renin–angiotensin blockade and select the starting dose from prior treatment and patient tolerance.',
    'Explain urgent evaluation for swelling of the tongue, lips or throat, or difficulty breathing. Monitor for hypotension, hyperkalemia and renal deterioration after initiation and titration. A patient who develops intolerance needs reassessment of volume status, interacting drugs and a suitable alternative rather than automatic overlap with the previous ACE inhibitor. The essential transition rule is independent of whether the eventual ARNI starting dose is low or standard.')],['ARNILABEL','AHA2022'])

add('Foundational treatment and safe prescribing','Select the Reduced ARNI Starting Dose for Minimal Prior RAS Exposure',
 'A stable, euvolemic patient with symptomatic HF and EF 30% has not previously taken an ACE inhibitor or ARB. BP is 116/72 mmHg, eGFR 48 mL/min/1.73 m² and potassium 4.4 mmol/L. Sacubitril/valsartan is selected. Which starting regimen matches the adult prescribing information?',
 'Sacubitril/valsartan 24/26 mg twice daily',[
 ('Sacubitril/valsartan 49/51 mg twice daily','This is the usual adult starting dose when no dose-reduction circumstance applies. Lack of prior ACE inhibitor or ARB exposure calls for half that usual starting dose.'),
 ('Sacubitril/valsartan 97/103 mg twice daily','This is the target maintenance dose, not an appropriate initial regimen in a treatment-naive patient; initiation must account for hypotension and renal/potassium effects.'),
 ('Sacubitril/valsartan 49/51 mg once daily','Reducing frequency is not the labeled adult low-start strategy. The lower-strength twice-daily regimen preserves the intended dosing schedule.')],
 [S('Match Starting Dose to Exposure and Tolerance','**The adult label recommends half the usual starting dose when the patient is not taking an ACE inhibitor or ARB, or was taking only a low dose.** This corresponds to 24/26 mg twice daily.',
    'The usual starting regimen is 49/51 mg twice daily. Severe renal impairment, eGFR <30 mL/min/1.73 m², also warrants half the usual starting dose under the label; the eGFR of 48 alone does not create that severe-renal category.',
    'Assess baseline blood pressure and volume status. Correct important volume depletion and avoid assuming that a normal creatinine excludes susceptibility to hypotension.'),
  S('Titrate and Monitor','**Double the dose every two to four weeks toward 97/103 mg twice daily as tolerated.** The target is not a requirement to escalate despite symptomatic hypotension, hyperkalemia or significant renal deterioration.',
    'Recheck pressure, orthostatic symptoms, creatinine/eGFR and potassium after initiation and dose changes. Review diuretic requirements and other pressure-lowering or potassium-raising drugs.',
    'Each tablet strength lists sacubitril and valsartan separately; do not confuse a combined strength with the valsartan dose alone or replace the formulation milligram-for-milligram with ordinary valsartan. Continue the other indicated foundational classes while titrating safely. A reduced starting dose is a route to sustainable treatment, not an instruction to leave the patient indefinitely at the initial dose without reassessment.')],['ARNILABEL','ACC2024'])

add('Foundational treatment and safe prescribing','Use an Evidence-Based Beta Blocker After Compensation',
 'A patient hospitalized with HF and EF 25% is now euvolemic and clinically stable, without inotropes, hypoperfusion, important bradycardia or AV block. There is no prior beta-blocker treatment. Which initial prescription uses an evidence-based agent, formulation and starting dose under AHA/ACC/HFSA 2022?',
 'Metoprolol succinate extended release 12.5 mg once daily',[
 ('Metoprolol tartrate 12.5 mg twice daily','Short-acting tartrate can be used for other clinical purposes, but is not interchangeable with the sustained-release succinate regimen carrying the specified HFrEF mortality evidence. A low dose does not remove the formulation distinction.'),
 ('Bisoprolol 10 mg once daily','Bisoprolol is an evidence-based agent, but 10 mg daily is its target dose rather than the treatment-naive starting dose. Initiation generally uses 1.25 mg daily followed by tolerated titration.'),
 ('Carvedilol 25 mg twice daily','Carvedilol is an evidence-based agent, but 25 mg twice daily is a target-level regimen. A treatment-naive compensated patient generally starts at 3.125 mg twice daily and increases gradually with reassessment.')],
 [S('Evidence Is Agent and Formulation Specific','**AHA/ACC/HFSA 2022 identifies bisoprolol, carvedilol and sustained-release metoprolol succinate as mortality-proven HFrEF beta blockers.** Select one rather than assuming a class effect for every beta blocker.',
    'Metoprolol succinate starts at 12.5–25 mg once daily and targets 200 mg once daily when tolerated. Bisoprolol starts at 1.25 mg once daily and targets 10 mg once daily.',
    'Carvedilol starts at 3.125 mg twice daily; guideline target doses are 25–50 mg twice daily depending on patient characteristics and tolerance. Its alpha-1 blockade can affect pressure tolerance.'),
  S('Initiation Is Different From Continuation During Illness','**Begin at low dose after clinical compensation and increase with reassessment.** Starting or increasing treatment during shock, active hypoperfusion or an escalating inotrope requirement can worsen hemodynamics.',
    'Monitor heart rate, pressure, congestion, fatigue and conduction. Symptomatic bradycardia, significant AV block and active bronchospasm require individualized assessment and may limit selection or dosing.',
    'A patient already receiving a beta blocker is a different decision from a treatment-naive patient: do not routinely withdraw chronic treatment for every admission, but reassess when shock or another major contraindication occurs. Early fatigue is not by itself proof of permanent intolerance. Aim for a tolerated evidence-based regimen alongside other foundational therapies rather than escalating solely to achieve a numerical pulse target.')],['AHA2022','ACC2024'])

R['DAPALABEL']=('FDA dapagliflozin prescribing information, 2026','https://www.accessdata.fda.gov/drugsatfda_docs/label/2026/202293s035lbl.pdf')

add('Foundational treatment and safe prescribing','MRA Initiation Requires Both Renal and Potassium Eligibility',
 'A patient with NYHA II HF and EF 30% is receiving tolerated foundational treatment without an MRA. Repeat potassium is 5.2 mmol/L and eGFR is 42 mL/min/1.73 m². Under AHA/ACC/HFSA 2022 guidance, which plan is appropriate?',
 'Address reversible hyperkalemia and repeat laboratory assessment before starting an MRA',[
 ('Start spironolactone 12.5 mg daily with a potassium check in one week','Low-dose spironolactone with early surveillance can be appropriate after initiation criteria are met. Renal eligibility does not cancel the requirement for potassium below 5.0 mmol/L; monitoring cannot substitute for correcting the current elevation first.'),
 ('Start eplerenone 25 mg on alternate days with a potassium check in one week','An alternate-day regimen can be appropriate with reduced renal function in an otherwise eligible patient. Eplerenone still raises potassium, so agent selection and a lower frequency do not remove the current initiation barrier.'),
 ('Replace the RAS inhibitor with an MRA after stopping the former','Replacing one indicated class is not the default response to modest hyperkalemia. The current potassium level also constrains MRA initiation, so contributors and repeat values should be assessed before restructuring the complementary regimen.')],
 [S('Apply Both Initiation Conditions','**AHA/ACC/HFSA 2022 recommends spironolactone or eplerenone in eligible symptomatic HFrEF when eGFR >30 mL/min/1.73 m² and potassium <5.0 mmol/L.** This patient satisfies only the renal condition.',
    'Verify the sample and review potassium supplements, potassium-containing salt substitutes, NSAIDs, trimethoprim and concurrent renin–angiotensin treatment. Identify acute kidney injury or volume disturbances.',
    'Do not automatically withdraw all beneficial medicines from a single modest elevation. Correct contributors and use a monitored reassessment plan.'),
  S('Dosing and Surveillance After Eligibility Is Established','**Spironolactone commonly starts at 12.5–25 mg daily, with target 25–50 mg daily; eplerenone commonly starts at 25 mg daily, targeting 50 mg daily.** Reduced renal function may require a lower or alternate-day starting regimen.',
    'The named guideline advises renal and potassium checks approximately one week and four weeks after initiation or intensification, then about every six months when stable; test more often with instability or increased risk.',
    'If potassium cannot be maintained below 5.5 mmol/L during treatment, discontinue the MRA under this framework to avoid life-threatening hyperkalemia. Initiation and continuation thresholds are different decisions. Spironolactone can cause gynecomastia or breast discomfort; eplerenone may be selected for those effects but still requires renal, potassium and interaction review. Document a follow-up date so temporary deferral does not become an unexamined permanent treatment gap.')],['AHA2022','ACC2024'])

add('Foundational treatment and safe prescribing','SGLT2 Treatment for HF Does Not Require Diabetes',
 'A stable patient with symptomatic HF and EF 32% has HbA1c 5.5%, eGFR 38 mL/min/1.73 m² and no volume depletion. Dapagliflozin is being considered for HF. Which plan is appropriate under its US prescribing information?',
 'Start dapagliflozin 10 mg once daily',[
 ('Start dapagliflozin 5 mg once daily','A 5-mg starting dose is used for glycemic control in eligible patients, but the adult HF regimen is 10 mg daily. Kidney function of 38 does not require a lower HF starting dose under the cited label.'),
 ('Start dapagliflozin 10 mg on alternate days','Alternate-day dosing may appear a cautious response to CKD, but it is not the labeled HF regimen. At eGFR 38, use the indicated daily dose after assessing volume status and other safety considerations.'),
 ('Defer initiation until eGFR is at least 45 mL/min/1.73 m²','The eGFR 45 limitation concerns glycemic efficacy rather than the separate HF indication. The cited US label permits initiation for HF at this patient’s eGFR, with renal and volume monitoring.')],
 [S('Indication and Renal Context','**Dapagliflozin inhibits proximal tubular SGLT2 and has an adult HF indication independent of diabetes.** Its clinical use in HF is not simply glucose lowering in a patient with an abnormal HbA1c.',
    'The HF dose is 10 mg once daily. Under the cited US label, initiation is not recommended below eGFR 25 mL/min/1.73 m²; patients already treated may continue below that threshold for the specified cardiorenal indications.',
    'Assess renal function and correct volume depletion before starting. Glycemic-control restrictions should not be substituted for the separate HF dosing instructions.'),
  S('Anticipate Preventable Adverse Events','**Counsel about genital fungal infection, volume depletion and ketoacidosis that may occur without marked hyperglycemia.** Nausea, vomiting, abdominal pain or unexplained breathlessness warrant assessment rather than reassurance from a near-normal glucose.',
    'Withhold dapagliflozin for at least three days, if possible, before surgery or procedures involving prolonged fasting. Restart when clinically stable and oral intake has resumed; acute illness or prolonged poor intake may require temporary interruption.',
    'Review concurrent diuretics and symptoms of orthostasis. A small early eGFR dip can be hemodynamic, but progressive deterioration requires assessment for hypovolemia, illness and other causes. Avoid assuming that the absence of diabetes abolishes every adverse-effect risk. Provide a clear sick-day and restart plan while preserving the purpose of long-term HF treatment.')],['DAPALABEL','AHA2022','ACC2024'])

R['KDIGO2024']=('KDIGO CKD guideline, 2024: RAS inhibitor monitoring','https://kdigo.org/wp-content/uploads/2024/03/KDIGO-2024-CKD-Guideline.pdf')

add('Foundational treatment and safe prescribing','Review Nonessential Pressure-Lowering Treatment Before Abandoning HF Therapy',
 'A stable patient with EF 28% develops mild orthostatic dizziness after treatment changes. Seated BP is 100/64 mmHg, with a symptomatic postural fall. Pulse is 76/min; the patient is warm, euvolemic and has stable renal function and potassium. Medicines include sacubitril/valsartan, carvedilol, spironolactone, dapagliflozin and amlodipine prescribed solely for previous hypertension. No loop diuretic is required. Which medication should be reviewed for withdrawal first?',
 'Amlodipine',[
 ('Carvedilol','Reducing beta blockade can be necessary with symptomatic bradycardia or persistent intolerance after reversible causes are addressed. Pulse is 76/min, perfusion is preserved and a nonessential pressure-lowering drug remains, favoring preservation of carvedilol initially.'),
 ('Spironolactone','MRA reduction may be necessary with hyperkalemia, significant renal deterioration or persisting intolerance. Its pressure effect at HF doses is relatively modest and those limiting findings are absent, so it is not the first medicine to remove here.'),
 ('Sacubitril/valsartan','ARNI can contribute to hypotension and may require dose adjustment if symptoms persist. However, it has an HF outcome indication, whereas amlodipine has no remaining compelling indication in the supplied patient.')],
 [S('Assess Symptoms, Perfusion and Volume','**A low pressure reading is not equivalent to cardiogenic shock.** Determine whether symptoms correlate with orthostasis and assess mentation, peripheral perfusion, urine output and congestion.',
    'Look for diarrhea, poor intake, recent diuretic escalation, infection and other reversible causes. Review all prescriptions, including alpha blockers, nitrates and drugs prescribed outside the HF clinic.',
    'A patient with cool extremities, oliguria or worsening organ function needs urgent evaluation; the stable scenario here supports a deliberate medication review.'),
  S('Preserve Complementary Outcome Benefit','**Remove or reduce pressure-lowering treatment without a current compelling indication when feasible.** Amlodipine can treat hypertension or angina but is not a foundational HFrEF outcome therapy.',
    'If there is no congestion, reassess whether the loop dose remains necessary. Persistent symptomatic hypotension may still require individualized adjustment of HF medicines; do not force target doses despite intolerance.',
    'When possible, retain tolerated doses from complementary classes rather than maximizing one while eliminating the others. Bradycardia, renal dysfunction and hyperkalemia can change which medicine is adjusted. Recheck standing pressure and symptoms after intervention and document a plan to reassess temporarily reduced treatment. This sequence is patient-specific and does not make every antihypertensive dispensable when a separate indication remains.')],['ACC2024','AHA2022'])

add('Foundational treatment and safe prescribing','A Modest Creatinine Rise After ACE Inhibition Requires Context',
 'A patient with stable HFrEF and CKD starts an ACE inhibitor because ARNI is not feasible. Two weeks later, creatinine has risen from 1.5 to 1.8 mg/dL and is stable on repeat testing. Potassium is 4.6 mmol/L, BP 116/70 mmHg, and there is no hypovolemia or new illness. Which approach best fits KDIGO 2024 guidance?',
 'Continue the ACE inhibitor with planned renal and potassium monitoring',[
 ('Interrupt the ACE inhibitor and repeat renal testing after one week','Interruption can be necessary with progressive renal deterioration, significant hypotension or uncontrolled hyperkalemia. A stable 20% rise with acceptable pressure and potassium does not meet the cited creatinine trigger for routine interruption.'),
 ('Halve the ACE inhibitor dose and maintain the reduced dose','Dose reduction may be appropriate when adverse effects persist after contributors are addressed. Here the change is within the cited acceptable early range, so automatic dose reduction sacrifices indicated treatment without a supplied intolerance.'),
 ('Replace the ACE inhibitor with an ARB to prevent the filtration change','An ARB may substitute for ACE-inhibitor cough or other appropriate intolerance. Both reduce angiotensin-mediated efferent arteriolar tone, so changing classes does not inherently eliminate this hemodynamic filtration response.')],
 [S('Recognize the Hemodynamic Effect','**ACE inhibition reduces angiotensin-mediated efferent arteriolar tone and can lower intraglomerular pressure.** Serum creatinine may increase without direct tubular toxicity.',
    'The change here is (1.8−1.5)/1.5 ×100 = 20%. KDIGO 2024 advises continuing ACE inhibitor or ARB unless creatinine rises by more than 30% within four weeks of initiation or dose increase.',
    'This is an ACEi/ARB practice point in CKD, not a universal permission to ignore renal deterioration on every HF medicine or during shock.'),
  S('Identify Findings That Change the Plan','**Check pressure, potassium, volume status and the direction of change.** A progressive rise, symptomatic hypotension or uncontrolled hyperkalemia warrants reassessment and may require dose reduction or interruption.',
    'Review NSAIDs, diuretic-related depletion, sepsis, obstruction and possible renovascular disease when appropriate. A larger early rise should trigger investigation rather than being attributed automatically to benign adaptation.',
    'KDIGO recommends checking pressure, creatinine and potassium within two to four weeks after starting or increasing ACEi/ARB, with timing individualized to baseline risk. HF or unstable patients may require earlier checks. Continue longitudinal surveillance after an initially acceptable result. Preserving indicated treatment and recognizing genuine acute kidney injury are compatible goals when decisions follow the full clinical picture.')],['KDIGO2024','ACC2024'])

R['DIAMOND']=('DIAMOND patiromer randomized trial, 2022','https://pmc.ncbi.nlm.nih.gov/articles/PMC9622299/')
R['TREDHF']=('TRED-HF randomized pilot trial, 2018 online/2019 print','https://doi.org/10.1016/S0140-6736(18)32484-X')

add('Foundational treatment and safe prescribing','Potassium Control and Proven HF Outcome Benefit Are Different Endpoints',
 'A patient with HFrEF has recurrent treatment-limiting hyperkalemia despite correction of supplements and other reversible causes. The HF team considers patiromer to facilitate renin–angiotensin–aldosterone inhibitor treatment. Which interpretation of DIAMOND and AHA/ACC/HFSA 2022 guidance is most accurate?',
 'Patiromer can improve potassium control and treatment maintenance, but this does not establish an independent mortality benefit',[
 ('DIAMOND established reduced cardiovascular mortality as its definitive primary result','The trial’s final primary endpoint was change in serum potassium, after alteration of the original outcome plan. Improved potassium-related results cannot be relabeled as a proven mortality reduction.'),
 ('DIAMOND found potassium lowering but no improvement in maintaining MRA treatment','The trial assessed more than a laboratory difference: patiromer reduced MRA dose-reduction events as well as recurrent hyperkalemia. That treatment-maintenance finding should be preserved without inflating it into a mortality claim.'),
 ('DIAMOND randomized unselected patients before testing tolerance of RAAS inhibitor optimization','The study used a run-in incorporating patiromer and RAAS inhibitor optimization before randomized withdrawal. That selection affects generalizability to patients unable to complete optimization and differs from an unselected initiation trial.')],
 [S('Interpret the Trial as Conducted','**DIAMOND evaluated patiromer in HFrEF with current or previous RAAS inhibitor-related hyperkalemia.** A run-in phase combined binder treatment with optimization before randomized withdrawal to patiromer or placebo.',
    'The final primary endpoint was the adjusted mean change in potassium. Patiromer improved potassium control and reduced recurrent hyperkalemia and MRA dose-reduction events.',
    'The selected run-in population and changed primary endpoint matter when judging generalizability. This study does not establish that the binder itself reduces mortality.'),
  S('Build a Safe Treatment-Retention Plan','**Treat the degree and urgency of hyperkalemia before deciding long-term drug retention.** Review ECG and clinical context when indicated, kidney function, interacting medicines, supplements and dietary potassium sources.',
    'AHA/ACC/HFSA 2022 described improved clinical outcomes from binder-facilitated RAAS inhibitor continuation as uncertain. Distinguish that uncertainty from evidence that binders can lower potassium.',
    'Patiromer is not a substitute for emergency treatment of life-threatening hyperkalemia. Ongoing treatment requires attention to gastrointestinal tolerance, magnesium and separation from interacting oral medicines according to its label. If potassium cannot be maintained within a safe range, adjust or interrupt the implicated therapy and reassess. A monitored strategy should preserve appropriate HF benefit without treating the desire to maintain a medicine as a reason to disregard unsafe laboratory results.')],['DIAMOND','AHA2022','KDIGO2024'],style='direct')

add('Foundational treatment and safe prescribing','TRED-HF Supports Continued Therapy After Remission',
 'An asymptomatic patient previously treated for dilated cardiomyopathy now has normalized LV dimensions and EF 56%. There is no medication intolerance. The patient asks to stop all HF medicines because the heart has recovered. Which response best reflects TRED-HF and guideline recommendations?',
 'Continue indicated HF therapy because remission does not reliably identify a group safe for routine withdrawal',[
 ('Offer phased withdrawal with scheduled imaging and biomarker surveillance','The TRED-HF withdrawal strategy included structured surveillance yet relapse was common. Monitoring can detect deterioration but does not establish that routine withdrawal is safe in an asymptomatic patient tolerating treatment.'),
 ('Continue the beta blocker but withdraw the renin–angiotensin inhibitor','Selective withdrawal may become necessary for a specific adverse effect or contraindication. Neither the normalized EF nor TRED-HF establishes that this particular residual regimen safely preserves remission in a patient without intolerance.'),
 ('Reduce disease-modifying therapy to initial doses for long-term maintenance','Dose reduction can address intolerance after individual assessment. There is no supplied intolerance and the trial does not validate routine de-escalation to starting doses merely because ventricular dimensions and EF have normalized.')],
 [S('The Trial Tested Withdrawal in Apparent Recovery','**TRED-HF was an open-label randomized pilot study in recovered dilated cardiomyopathy.** Participants had improved function and favorable clinical and structural findings before withdrawal was considered.',
    'Within the first six months, 11 of 25 patients assigned to phased withdrawal relapsed, compared with none of 26 assigned initially to continued treatment: 44% versus 0%.',
    'The endpoint captured objective deterioration as well as clinical recurrence. It was not simply a comparison of deaths or symptomatic hospital admissions.'),
  S('Apply Remission Evidence Without Overgeneralization','**AHA/ACC/HFSA 2022 recommends continuing treatment in HF with improved EF to prevent relapse, even when symptoms resolve.** Improvement can reflect the benefit of therapy rather than disappearance of susceptibility.',
    'TRED-HF does not prove that every medicine has identical withdrawal risk in every etiology, nor does it eliminate individualized adjustment for adverse effects. It does argue against routine wholesale cessation based on one normal scan.',
    'Discuss adherence, pregnancy plans, competing illnesses and tolerability. Follow symptoms, function and relevant imaging or biomarkers as clinically indicated. Loop-diuretic reduction in a persistently euvolemic patient is a different decision from stopping the disease-modifying regimen. If treatment must be interrupted, document why, monitor closely and revisit reintroduction rather than describing remission as a permanent cure.')],['TREDHF','AHA2022'])

R['TRANSFORMHF']=('TRANSFORM-HF randomized trial, 2023','https://jamanetwork.com/journals/jama/fullarticle/2800428')
add('Foundational treatment and safe prescribing','Loop Diuretics Are Titrated to Congestion Rather Than a Prognostic Target Dose',
 'A patient with HFrEF remains well perfused and euvolemic after several weeks of stable weight and examination. Foundational treatment is tolerated. Furosemide is still being taken at the higher dose used during a recent congestive episode. What is the most appropriate prescribing principle?',
 'Reassess and use the lowest loop dose that maintains euvolemia while continuing indicated foundational treatment',[
 ('Retain the admission loop dose until the next EF reassessment','A recent high dose may remain necessary if congestion recurs, but EF is not the principal loop-titration target. Stable euvolemia should prompt review of dose need rather than waiting for an unrelated imaging milestone.'),
 ('Convert the loop to symptom-triggered treatment immediately','Selected stable patients can use an individualized flexible or intermittent regimen after assessment. Abruptly making symptoms the only trigger can miss early recurrent congestion; maintenance needs and a weight/action plan should be reviewed first.'),
 ('Switch to torsemide to provide a proven survival advantage','Torsemide may suit absorption, response or adherence considerations, but its routine replacement of furosemide has not established a survival advantage. Drug selection does not remove the need to reassess the dose required for euvolemia.')],
 [S('Mechanism and Treatment Goal','**Loop diuretics inhibit the Na–K–2Cl cotransporter in the thick ascending limb and relieve sodium and water retention.** Their practical dose depends on congestion, kidney function, absorption and the observed response.',
    'AHA/ACC/HFSA 2022 lists oral furosemide 20–40 mg once or twice daily as a common initial regimen. Established patients may require substantially different doses, which should not be copied from a generic starting range.',
    'The aim is sustained euvolemia, not the maximum possible urine output or routine escalation to a fixed high dose.'),
  S('Reduce Excess Exposure Without Inviting Recurrent Congestion','**Review symptoms, weight trend, orthostasis, venous pressure, edema, renal function and electrolytes before adjustment.** Some patients need continuing maintenance treatment to avoid recurrent fluid retention.',
    'Monitor sodium, potassium and magnesium, especially with combination diuretics. Hypokalemia can increase arrhythmic and digoxin-related risk; excessive diuresis can produce hypotension and renal dysfunction.',
    'Provide an individualized weight and symptom action plan and a review date after dose changes. Do not assume one normal visit means every patient can stop diuretics permanently. Conversely, ARNI and SGLT2 treatment or improved HF status may lower loop requirements. Keep relief of congestion and outcome-modifying therapy conceptually distinct while recognizing that both are important components of care.')],['AHA2022','ESC2021','ACC2024','TRANSFORMHF'])

add('Foundational treatment and safe prescribing','NSAID Exposure Can Blunt Diuresis and Precipitate Congestion',
 'A previously stable patient with EF 30% develops edema, rising blood pressure and reduced response to the usual loop dose after starting oral ibuprofen for joint pain. Adherence to HF medicines is confirmed. Which mechanism best explains the new deterioration?',
 'Renal prostaglandin inhibition causing sodium retention and reduced diuretic responsiveness',[
 ('Precapillary arteriolar dilation increasing dependent capillary hydrostatic pressure','This mechanism helps explain dihydropyridine calcium-channel-blocker ankle edema, which need not reflect generalized sodium retention. It does not best explain ibuprofen-associated pressure rise and loss of loop responsiveness.'),
 ('Direct myocardial calcium-channel inhibition reducing ventricular contractility','Negative inotropy contributes to concerns with verapamil or diltiazem in reduced-EF HF. The principal supplied NSAID mechanism is altered renal prostaglandin signaling and sodium handling rather than therapeutic calcium-channel blockade.'),
 ('PPAR-gamma activation promoting renal sodium retention and volume expansion','Thiazolidinediones can worsen HF through this pathway and are plausible drug-related causes of fluid retention. Ibuprofen does not act through PPAR-gamma activation; the exposure identifies prostaglandin inhibition instead.')],
 [S('Recognize a Reversible Drug Trigger','**Systemic NSAIDs can worsen HF through renal prostaglandin inhibition, sodium/water retention, increased vascular resistance and reduced diuretic response.** COX-2 selectivity does not eliminate these concerns.',
    'Review over-the-counter analgesics as well as prescription drugs. The temporal association supports a trigger but does not exclude another concurrent cause of decompensation.',
    'Assess congestion, perfusion, kidney function and potassium promptly. Coordinate discontinuation of the precipitating drug and a safer pain-management plan while treating the HF deterioration.'),
  S('Compare Other Important Drug Hazards','**Different medicines worsen HF through different mechanisms.** Avoid treating every peripheral edema or creatinine change as the same adverse effect.',
    'Thiazolidinediones can cause fluid retention and should be avoided in symptomatic HF. Diltiazem and verapamil have negative inotropic effects and are generally unsuitable in HFrEF.',
    'Amlodipine may be used for a separate pressure or angina indication but is not foundational HF treatment; ankle edema on it is not automatically proof of cardiogenic volume overload. Review antiarrhythmic and potassium-raising interactions according to the individual regimen. A complete medication reconciliation can identify a reversible contributor before escalating diuretics indefinitely or declaring progression despite optimal treatment.')],['AHA2022','ACC2024'])

R['IVABRADINE']=('FDA ivabradine prescribing information','https://www.accessdata.fda.gov/drugsatfda_docs/label/2021/206143s008%2C209964s002lbl.pdf')
R['AHEFT']=('A-HeFT randomized trial, 2004','https://doi.org/10.1056/NEJMoa042934')
R['HISDNLABEL']=('Isosorbide dinitrate/hydralazine prescribing information','https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=8f54d5a3-169f-48dd-9250-2c176d2bd9ad&type=display')

add('Additional therapy, comorbidity and preserved EF','Ivabradine Requires Sinus Rhythm and Residual Tachycardia',
 'A stable patient has NYHA II HF, EF 30% and sinus rhythm at 82/min despite maximally tolerated carvedilol and other indicated foundational therapy. Further beta-blocker titration causes symptomatic hypotension. Which additional treatment most directly fits the residual sinus-rate indication?',
 'Ivabradine',[
 ('Digoxin','Digoxin may be considered in selected persistently symptomatic reduced-EF HF and provides ventricular rate control in selected AF. It does not match the specific sinus-rate, EF and maximally tolerated beta-blocker eligibility pattern as directly as ivabradine.'),
 ('Hydralazine–isosorbide dinitrate','This combination has defined add-on and RAS-intolerance indications and lowers preload and afterload. Residual sinus tachycardia alone does not establish those indications; additional vasodilation may also be limited by this patient’s pressure tolerance.'),
 ('Vericiguat','Vericiguat is assessed in selected worsening HF using clinical history and eligibility conditions. It does not selectively address residual sinus-rate elevation, and the stem supplies no recent worsening event to match that add-on pathway.')],
 [S('Match the Mechanism to the Rhythm','**Ivabradine inhibits the sinoatrial If current and lowers sinus rate.** It is not a ventricular rate-control substitute for AF.',
    'The US adult HF indication requires stable symptomatic chronic HF, LVEF ≤35%, sinus rhythm and resting heart rate ≥70/min despite maximally tolerated beta blockade or a beta-blocker contraindication.',
    'The treatment aims to reduce worsening-HF hospitalization. It does not replace the broader survival evidence and complementary mechanisms of foundational therapy.'),
  S('Dose, Monitoring and Interactions','**The usual adult starting dose is ==5 mg twice daily== with food.** Reassess after two weeks and adjust toward a resting rate of ==50–60/min==; the maximum is ==7.5 mg twice daily==.',
    'Start at 2.5 mg twice daily when conduction disease or susceptibility to bradycardic compromise warrants caution. Reduce treatment for rate below 50/min or bradycardic symptoms and stop if these persist at the lowest dose.',
    'Monitor for AF, bradycardia and luminous visual phenomena. Strong CYP3A4 inhibitors are contraindicated; avoid clinically important exposure-increasing interactions such as verapamil or diltiazem. Assess conduction, pacemaker dependence, blood pressure and pregnancy risk before prescribing. New AF changes the rationale for continued therapy. A drug that lowers sinus rate is useful only when the patient matches the rhythm-specific indication and has already had an appropriate beta-blocker assessment.')],['IVABRADINE','AHA2022'])

add('Additional therapy, comorbidity and preserved EF','Hydralazine–Isosorbide Dinitrate Has a Defined Add-On Evidence Base',
 'A patient who self-identifies as African American has persistent NYHA III HFrEF despite maximally tolerated foundational treatment. BP is 126/76 mmHg. There is no PDE5 inhibitor or riociguat use and no other contraindication. Which additional vasodilator strategy matches AHA/ACC/HFSA 2022 guidance?',
 'Hydralazine plus isosorbide dinitrate',[
 ('Hydralazine plus isosorbide mononitrate','Both drugs have vasodilator uses, but substituting mononitrate does not reproduce the specific combination tested in the population-based outcome evidence. Use the studied dinitrate regimen rather than assuming nitrate formulations are outcome-equivalent.'),
 ('Isosorbide dinitrate alone','Dinitrate monotherapy can relieve angina and reduce preload, but the specified HF outcome evidence concerns its combination with hydralazine. The isolated nitrate does not reproduce complementary arterial and venous vasodilation.'),
 ('Hydralazine plus amlodipine','These agents can lower arterial pressure in selected hypertension settings. Amlodipine does not replace the nitrate component of the HF outcome regimen, and a separate blood-pressure indication is not supplied.')],
 [S('Preserve the Studied Population and Background Treatment','**AHA/ACC/HFSA 2022 recommends hydralazine–isosorbide dinitrate for self-identified African American patients with NYHA III–IV HFrEF receiving optimal therapy.** A-HeFT supports the population-specific add-on evidence.',
    'The trial used self-identification rather than a genetic assay. Do not infer an individual response from race alone or use this evidence to withhold foundational therapy from any group.',
    'The combination may also be considered in selected symptomatic HFrEF when ARNI, ACE inhibitor or ARB cannot be used because of intolerance or renal limitations; the evidence and recommendation strength differ.'),
  S('Prescribe the Combination Safely','**The fixed-dose tablet contains hydralazine 37.5 mg and isosorbide dinitrate 20 mg.** Start one tablet three times daily and titrate as tolerated to two tablets three times daily: 75/40 mg per dose.',
    'Hydralazine primarily reduces arterial afterload and nitrate therapy provides venodilation through nitric-oxide signaling. Headache, dizziness and hypotension can limit adherence and titration.',
    'Nitrates must not be combined with PDE5 inhibitors or riociguat because of severe hypotension risk. Monitor pressure and symptoms, and assess hydralazine-related lupus-like illness when compatible features develop. Three-times-daily treatment creates a real adherence burden. Explain the indication and preserve tolerated foundational therapy rather than assuming symptom improvement makes the rest of the regimen unnecessary.')],['AHA2022','AHEFT','HISDNLABEL'])

R['DIGLABEL']=('FDA digoxin prescribing information, 2024','https://www.accessdata.fda.gov/drugsatfda_docs/label/2024/009330s039lbl.pdf')
R['DIGITHF']=('DIGIT-HF randomized trial, 2025','https://doi.org/10.1056/NEJMoa2415471')

add('Additional therapy, comorbidity and preserved EF','Digoxin Exposure Must Be Reassessed When Kidney Function Declines',
 'An older patient with HFrEF has been stable on digoxin 0.125 mg daily. After an intercurrent illness, kidney function deteriorates and amiodarone is added for a separate arrhythmic indication. Nausea and new bradycardia develop. Which next step is most appropriate?',
 'Withhold digoxin pending urgent clinical, ECG, electrolyte and appropriately timed concentration assessment',[
 ('Reduce digoxin to alternate-day dosing and arrange a routine outpatient trough next week','A lower maintenance frequency can be appropriate after renal and interaction review in a stable asymptomatic patient. New bradycardia with gastrointestinal symptoms warrants withholding and urgent assessment before selecting the revised regimen.'),
 ('Stop amiodarone alone and continue digoxin while arranging its next trough concentration','Amiodarone can contribute to bradycardia and increased digoxin exposure, and its indication requires review. Stopping it does not promptly reverse its long-lasting interaction or remove already accumulated digoxin in this symptomatic patient.'),
 ('Administer digoxin-specific antibody fragments before obtaining ECG or electrolyte findings','Antibody fragments are appropriate for life-threatening glycoside toxicity, such as dangerous arrhythmia or significant hyperkalemia in the appropriate context. The supplied symptoms require urgent severity assessment, but do not alone establish an immediate empiric antidote indication.')],
 [S('Identify Accumulation and Interactions','**Digoxin has a narrow therapeutic margin and substantial renal elimination.** Dose requirements depend on kidney function, lean body mass, age and interacting medicines.',
    'Amiodarone can increase digoxin exposure and requires dose/frequency review with monitoring. Hypokalemia and hypomagnesemia increase susceptibility to adverse cardiac effects even without an extreme serum concentration.',
    'Assess nausea, anorexia, visual symptoms, confusion, bradyarrhythmia and ventricular arrhythmia in the full context. A concentration alone does not replace examination and ECG assessment.'),
  S('Monitor a Low-Concentration Regimen','**The AHA/ACC/HFSA 2022 HF table specifies an individualized concentration target of 0.5 to <0.9 ng/mL.** A customary 0.125–0.25 mg daily range is not an instruction to ignore renal or body-size adjustment.',
    'Obtain a level after the distribution phase, generally just before the next dose or at least six hours after the previous dose according to prescribing guidance. Interpret timing and recent dose changes before comparing results.',
    'Withhold or adjust treatment when toxicity is suspected and correct relevant electrolyte abnormalities. Life-threatening manifestations can require digoxin-specific antibody fragments and specialist emergency management. After recovery, reconsider whether digoxin remains indicated and select a sustainable dose and monitoring schedule. Do not extrapolate a dose or concentration target from digitoxin: related mechanisms do not make the two medicines pharmacokinetically interchangeable.')],['DIGLABEL','AHA2022'])

R['DECISION']=('DECISION low-dose digoxin randomized trial, 2026','https://doi.org/10.1038/s41591-026-04406-6')
add('Additional therapy, comorbidity and preserved EF','DIGIT-HF Tested Digitoxin Rather Than Interchangeable Glycoside Treatment',
 'Which conclusion follows from the original DIGIT-HF randomized report when considering additional treatment for symptomatic reduced-EF HF?',
 'Digitoxin reduced the composite of all-cause death or first worsening-HF hospitalization in the studied population, without proving identical benefit for digoxin',[
 ('The trial demonstrated a statistically conclusive isolated all-cause mortality reduction','The primary composite was significant, but the reported mortality component confidence interval included no effect. Composite benefit cannot be renamed an established isolated survival effect.'),
 ('The trial validates the same milligram dose and serum target for digoxin','The drugs have different dosing, concentration ranges and elimination characteristics. A digitoxin regimen cannot be transferred directly to digoxin.'),
 ('The trial established digitoxin as a substitute for foundational HF treatment','Digitoxin was tested in addition to guideline-directed treatment, not as a replacement for the complementary therapies already indicated in HFrEF.')],
 [S('Population and Primary Endpoint','**DIGIT-HF randomized symptomatic chronic HF patients to digitoxin or placebo on background treatment.** Eligibility included EF ≤40% with NYHA III–IV or EF ≤30% with NYHA II.',
    'The primary endpoint was all-cause death or first hospitalization for worsening HF. In the modified intention-to-treat analysis, it occurred in 39.5% versus 44.1% over a median 36 months: HR 0.82, 95% CI 0.69–0.98.',
    'The all-cause mortality component had HR 0.86 with 95% CI 0.69–1.07. Retain the distinction between a significant composite and a component not independently established as significant.'),
  S('Drug-Specific Application','**The trial started digitoxin at 0.07 mg once daily with protocol-guided adjustment.** Its target serum range was 8–18 ng/mL, substantially different from the low-concentration digoxin HF target.',
    'Digitoxin depends less on renal elimination than digoxin, but still has a narrow therapeutic margin, important interactions and a need for clinical and laboratory surveillance. In DECISION (2026), low-dose digoxin in 1,001 patients with EF ≤50% did not significantly reduce total worsening-HF events or cardiovascular death: rate ratio 0.81, 95% CI 0.61–1.07. Its population, drug and recurrent-event endpoint differ from DIGIT-HF.',
    'Availability, local authorization, guideline interpretation and individual risk determine use. A positive add-on trial does not justify universal initiation or imply that every cardiac glycoside has identical contemporary outcome evidence. Explain potential benefit alongside adverse effects and avoid using a familiar drug name as a substitute for matching the actual trial intervention, population and monitoring protocol.')],['DIGITHF','DECISION','AHA2022'],style='direct')

R['VICTORIA']=('VICTORIA randomized trial, 2020','https://doi.org/10.1056/NEJMoa1915928')
R['VICTOR']=('VICTOR randomized trial, 2025','https://doi.org/10.1016/S0140-6736(25)01665-4')
R['VERILABEL']=('FDA vericiguat prescribing information, January 2026','https://www.accessdata.fda.gov/drugsatfda_docs/label/2026/214377s005lbl.pdf')
R['FCMLABEL']=('FDA ferric carboxymaltose prescribing information, 2026','https://www.accessdata.fda.gov/drugsatfda_docs/label/2026/203565s030lbl.pdf')

add('Additional therapy, comorbidity and preserved EF','Vericiguat Is an Additional Option After Worsening HF',
 'A patient with EF 30% remains NYHA III despite tolerated foundational therapy and was recently hospitalized for worsening HF. The patient is now euvolemic and stable, with sinus rate 62/min, BP 118/72 mmHg, ferritin 180 ng/mL and TSAT 27%. There is no pregnancy or relevant drug interaction. Which add-on most closely matches the residual-risk population tested in VICTORIA?',
 'Vericiguat',[
 ('Ivabradine','Ivabradine is an add-on for eligible symptomatic reduced-EF HF in sinus rhythm with resting rate at least 70/min despite maximally tolerated beta blockade. The rate of 62/min does not match that indication.'),
 ('Ferric carboxymaltose','Intravenous iron benefits selected symptomatic iron-deficient HF patients. Ferritin 180 with TSAT 27% does not meet the conventional ferritin 100–299 plus TSAT below 20% deficiency criterion.'),
 ('Metolazone','Metolazone provides sequential nephron blockade when congestion persists despite adequate loop treatment. This patient is euvolemic; additional natriuresis does not reproduce the residual-risk intervention tested in VICTORIA.')],
 [S('Trial Population and Endpoint','**Vericiguat stimulates soluble guanylate cyclase in the nitric-oxide–cGMP pathway.** VICTORIA studied symptomatic HF with EF <45% after recent worsening, added to usual treatment.',
    'The composite of cardiovascular death or first HF hospitalization occurred in 35.5% versus 38.5% over median follow-up of 10.8 months: HR 0.90, 95% CI 0.82–0.98.',
    'Retain the composite endpoint and worsening-HF context. VICTOR (2025) instead studied 6,105 patients without recent worsening; its primary composite was neutral: 18.0% versus 19.1%, HR 0.93, 95% CI 0.83–1.04. Mortality signals in secondary analyses must be interpreted with the neutral primary endpoint and testing hierarchy rather than presented as a positive primary trial.'),
  S('Use the Current Named Prescribing Regimen','**The January 2026 US label recommends ==5 mg once daily== with food, or ==2.5 mg once daily== for patients at risk of symptomatic hypotension.** Increase approximately every two weeks toward ==10 mg daily== as tolerated.',
    'Older trial-era tables commonly list 2.5 mg as the initial dose; date and jurisdiction matter when a question asks for the current regimen.',
    'Monitor pressure and anemia and review pregnancy precautions. Other soluble-guanylate-cyclase stimulators are contraindicated; PDE5 inhibitor coadministration is not recommended because of hypotension risk. Reassess congestion and foundational treatment before attributing every residual symptom to a need for another drug. Patient selection and tolerability remain necessary even when the recent clinical course resembles the trial.')],['VICTORIA','VICTOR','VERILABEL','AHA2022'])

add('Additional therapy, comorbidity and preserved EF','Iron Deficiency in HF Can Exist Without Anemia',
 'An 80-kg patient with NYHA III HF and EF 35% remains exercise-limited despite appropriate treatment. Hemoglobin is 13.2 g/dL, ferritin 160 ng/mL and TSAT 14%. There is no active infection or known iron overload. Which iron-directed strategy has the best supporting HF evidence?',
 'Assess intravenous ferric carboxymaltose and investigate the cause of deficiency',[
 ('Use oral ferrous sulfate as the initial HF exercise-capacity treatment','Oral iron can be appropriate in other deficiency settings, but oral therapy has not reproduced the exercise-capacity evidence supporting studied IV formulations in symptomatic HF. Route and formulation are consequential rather than interchangeable details.'),
 ('Repeat ferritin alone after three months before considering replacement','Repeat testing can clarify a transient or discordant laboratory pattern. Here ferritin 100–299 with TSAT below 20% meets the conventional HF definition, so relying on ferritin alone would miss relevant iron deficiency.'),
 ('Defer iron replacement and reassess when anemia develops','Deferral may be reasonable when iron deficiency is absent or treatment risks predominate. This patient has iron-deficient symptomatic HF without a supplied contraindication; anemia is not required for the relevant IV-iron benefit.')],
 [S('Interpret Ferritin With Transferrin Saturation','**The conventional HF definition is ferritin <100 ng/mL, or ferritin 100–299 ng/mL with TSAT <20%.** The latter identifies this patient despite a nonanemic hemoglobin.',
    'Iron availability affects skeletal-muscle and myocardial function as well as erythropoiesis. Evaluate dietary deficiency, malabsorption and occult blood loss rather than treating the laboratory pattern without seeking its cause.',
    'ESC 2026 recommends IV iron for symptoms and quality of life in symptomatic iron-deficient HFrEF and supports considering it to reduce HF hospitalization. Do not promise an established isolated mortality reduction. Ferritin-only definitions have limitations; TSAT <20% strengthens evidence of deficient availability in this case.'),
  S('Choose and Monitor a Specific Intravenous Regimen','**Dosing depends on formulation, weight and hemoglobin.** Under the cited US ferric-carboxymaltose HF table, this 80-kg patient with Hb 13.2 receives 1000 mg initially and 500 mg at week six.',
    'That schedule is not interchangeable with every iron product or with a generic anemia course. Further dosing requires repeat iron assessment and the applicable product protocol.',
    'Assess hypersensitivity history and phosphate risk. Ferric carboxymaltose can cause clinically important hypophosphatemia; correct a low baseline phosphate and monitor particularly with repeat treatment. Observe for infusion reactions and avoid extravasation. Continue assessment of the other causes of exercise limitation and the HF regimen: correcting deficiency complements that care rather than replacing it.')],['ESC2021','ESC2026','FCMLABEL'])

R['AF2023']=('ACC/AHA/ACCP/HRS atrial fibrillation guideline, 2023','https://doi.org/10.1161/CIR.0000000000001193')
R['SERVEHF']=('SERVE-HF randomized trial, 2015','https://doi.org/10.1056/NEJMoa1506459')
R['ADVENTHF']=('ADVENT-HF randomized trial, 2024','https://pubmed.ncbi.nlm.nih.gov/38142697/')
R['AASM2025']=('AASM central sleep apnea guideline, 2025','https://doi.org/10.5664/jcsm.11858')

add('Additional therapy, comorbidity and preserved EF','New AF With LV Dysfunction Warrants Early Rhythm-Control Assessment',
 'A patient with newly recognized persistent AF and EF 28% remains exercise-limited after decongestion. Ventricular rate is now 90/min, but a substantial AF burden preceded the decline in function. There is no important coronary or valve lesion. Under the 2023 US AF guideline, which strategy is most appropriate?',
 'Assess AF-mediated cardiomyopathy and pursue early rhythm-control evaluation, including catheter-ablation suitability',[
 ('Continue a rate-control strategy and reassess EF after three months before considering rhythm treatment','Rate control and HF therapy remain important, and delayed reassessment may suit other presentations. New HFrEF following substantial AF burden warrants early rhythm evaluation because an apparently acceptable resting rate does not exclude arrhythmia-mediated dysfunction.'),
 ('Intensify rate control to a resting rate below 80/min as the definitive first strategy','Stricter rate control can be considered when AF-mediated dysfunction is suspected, but a resting-rate target does not address AF burden, irregularity and lost atrial contribution. It should not replace early rhythm-control assessment in this presentation.'),
 ('Proceed to AV-junction ablation with resynchronization pacing','Ablation with an appropriate pacing strategy can benefit selected patients with refractory rates or unsuccessful rhythm control. The current patient has not yet undergone an early rhythm-control evaluation, and the supplied resting rate does not establish refractory rate control.')],
 [S('AF Can Cause or Worsen Ventricular Dysfunction','**AF-induced cardiomyopathy and AF-mediated worsening of another cardiomyopathy are related but distinct possibilities.** Duration, burden, rate, irregularity and loss of atrial contribution can all matter.',
    'The 2023 ACC/AHA/ACCP/HRS guideline recommends an early aggressive rhythm-control approach when new HFrEF and AF raise concern for arrhythmia-induced cardiomyopathy.',
    'Appropriate HFrEF patients can benefit from catheter ablation. Procedural candidacy depends on expected benefit, comorbidity, atrial disease, AF duration and patient preference, not EF alone.'),
  S('Integrate Rhythm, Rate and Stroke Prevention','**Rhythm treatment complements HF therapy and anticoagulation assessment.** Continue indicated ventricular treatment while reassessing function after control of the arrhythmia.',
    'Beta blockers and selected digoxin use can support rate control; avoid routine diltiazem or verapamil in significant LV systolic dysfunction. Hemodynamic instability attributable to AF creates an urgent cardioversion pathway.',
    'Assess thromboembolic risk and cardioversion/ablation anticoagulation requirements separately. Restoration of sinus rhythm does not automatically remove a continuing anticoagulation indication. Selected antiarrhythmics require structural-heart, renal, QT and interaction review. If AV-node ablation is eventually chosen for refractory rate control, evaluate resynchronization or conduction-system pacing as appropriate rather than assuming conventional RV pacing is neutral in a failing LV.')],['AF2023','AHA2022'])

add('Additional therapy, comorbidity and preserved EF','Sleep Apnea Event Suppression Does Not Establish Cardiovascular Benefit',
 'A patient with EF 30% has predominantly central sleep apnea on formal testing. When discussing adaptive servo-ventilation, which interpretation of SERVE-HF and subsequent evidence is most accurate?',
 'SERVE-HF found increased mortality with its tested ASV strategy despite apnea control; later evidence requires device-specific specialist interpretation',[
 ('SERVE-HF improved its primary clinical endpoint but increased mortality as a secondary trade-off','The trial improved apnea control, but the primary clinical composite was not significantly improved. An increase in mortality cannot be framed as the cost of a demonstrated primary clinical benefit.'),
 ('ADVENT-HF demonstrated a mortality reduction that superseded the SERVE-HF signal','ADVENT-HF used a different ASV approach and did not show a significant mortality or primary-composite benefit. Its result informs technology-specific uncertainty but does not establish a positive survival indication.'),
 ('AASM 2025 and ESC 2026 both recommend ASV for reduced-EF HF with predominant central apnea','The frameworks differ: AASM offers a conditional specialist-centered recommendation in selected CSA settings, while ESC 2026 retains a recommendation against ASV in HFrEF with predominant CSA. Device contraindications must also be respected.')],
 [S('Identify the Apnea Phenotype and Trial Intervention','**Central apnea reflects absent or reduced respiratory drive, whereas obstructive apnea involves upper-airway obstruction despite respiratory effort.** Formal testing helps distinguish the dominant pattern and select a pathway.',
    'SERVE-HF studied symptomatic HF with EF ≤45% and predominantly central apnea. All-cause mortality increased with ASV: HR 1.28; cardiovascular mortality HR 1.34.',
    'The primary endpoint was not significantly improved. Do not turn better overnight breathing indices into evidence of safer long-term cardiovascular outcomes.'),
  S('Apply Later Guidance Transparently','**ADVENT-HF used a different ASV approach and found no significant effect on its primary composite or all-cause mortality.** Trial technology, population and endpoint differences matter.',
    'AASM 2025 provides a conditional ASV recommendation for selected CSA settings, with shared decisions focused on symptoms or quality of life; HFrEF use is restricted to experienced centers with close monitoring. This does not override device labeling: ResMed ASV remains contraindicated in chronic symptomatic NYHA II–IV HF with LVEF ≤45% and moderate-to-severe predominant CSA.',
    'ESC 2026 retains a class III recommendation against ASV for HFrEF with predominant CSA because of mortality concerns; this differs from the conditional AASM approach. Name the framework rather than concealing the disagreement. Optimize HF care and assess other contributors to sleep-disordered breathing. For obstructive apnea, CPAP may improve sleep quality and symptoms, but do not promise HF survival benefit from that indication. The decision requires a sleep/HF specialist discussion of phenotype, technology, current restrictions, expected benefit and uncertainty.')],['SERVEHF','ADVENTHF','AASM2025','AHA2022','ESC2026'],style='direct')

R['DELIVER']=('DELIVER randomized trial, 2022','https://doi.org/10.1056/NEJMoa2206286')
R['FINEARTS']=('FINEARTS-HF randomized trial, 2024','https://doi.org/10.1056/NEJMoa2407107')
R['FINELABEL']=('FDA finerenone prescribing information, 2026','https://www.accessdata.fda.gov/drugsatfda_docs/label/2026/215341s011lbl.pdf')

add('Additional therapy, comorbidity and preserved EF','DELIVER Supports HF Treatment Beyond the Reduced-EF Trial Population',
 'A patient with established symptomatic HF, EF 58%, elevated filling-pressure evidence and no diabetes asks what DELIVER establishes about dapagliflozin. Which interpretation is most accurate?',
 'Dapagliflozin reduced worsening HF or cardiovascular death as a composite, without establishing an isolated cardiovascular mortality reduction',[
 ('The trial established a statistically significant cardiovascular mortality reduction as a separate endpoint','Cardiovascular death had HR 0.88 with 95% CI 0.74–1.05. The significant primary composite does not imply that this component was independently significant.'),
 ('The primary endpoint counted all recurrent HF admissions rather than time to a first event','Recurrent-event analyses can provide additional information about total disease burden. DELIVER’s primary endpoint was time to first worsening HF or cardiovascular death; its hazard ratio should not be relabeled as a recurrent-event rate ratio.'),
 ('The primary endpoint was HF hospitalization alone, with urgent visits assessed separately','HF hospitalization is important, but the primary worsening-HF definition also included urgent HF visits and was combined with cardiovascular death. Narrowing it to admission alone misstates the trial question.')],
 [S('Retain the Population and Endpoint','**DELIVER randomized patients with symptomatic HF and LVEF >40% to dapagliflozin 10 mg daily or placebo.** Its primary endpoint combined worsening HF, including hospitalization or an urgent visit, with cardiovascular death.',
    'Over median follow-up of 2.3 years, the primary outcome occurred in 16.4% versus 19.5%: HR 0.82, 95% CI 0.73–0.92.',
    'Worsening HF was reduced; the cardiovascular death component was not independently statistically significant. Describe the composite benefit without upgrading it to a separate mortality claim.'),
  S('Apply the Evidence to a Confirmed Syndrome','**An SGLT2 inhibitor is a treatment for eligible HF, not a diagnostic trial proving the syndrome from symptom improvement.** Confirm the clinical substrate and assess congestion and comorbidities.',
    'Diabetes is not required. Review renal eligibility using the selected drug label, volume status and risk of ketoacidosis or genital infection.',
    'Continue diuretic adjustment and treatment of hypertension, AF, obesity and kidney disease where indicated. A normal glucose does not eliminate adverse-effect counseling, and a high EF does not mean every source of dyspnea is HFpEF. The trial broadens the evidence across HF phenotypes while retaining the need for a defensible diagnosis and individualized safe prescribing.')],['DELIVER','DAPALABEL','ESC2026'],style='direct')

add('Additional therapy, comorbidity and preserved EF','Finerenone Uses an HF-Specific Renal-Based Dose Plan',
 'A patient with symptomatic HF and EF 55% is selected for finerenone. eGFR is 46 mL/min/1.73 m² and potassium 4.4 mmol/L. No other MRA is prescribed and interaction review is satisfactory. Under the 2026 US HF label, which starting and intended target doses are appropriate?',
 'Start 10 mg once daily and target 20 mg once daily',[
 ('Start 20 mg once daily and target 40 mg once daily','That starting/target pathway applies when eGFR at initiation is at least sixty. This patient’s eGFR belongs to the lower renal-function dosing category.'),
 ('Start 10 mg once daily and target 40 mg once daily','The lower starting dose is appropriate, but the HF target is also determined by renal function at initiation; the eGFR of forty-six supports a twenty-milligram target.'),
 ('Start 20 mg once daily and maintain 20 mg once daily','Twenty milligrams is the intended HF target for this baseline renal category, but initiation should use 10 mg daily. Choosing the eventual target does not remove the lower-start requirement and subsequent potassium/eGFR assessment.')],
 [S('Evidence and Treatment Population','**Finerenone is a nonsteroidal mineralocorticoid receptor antagonist.** FINEARTS-HF tested it in symptomatic HF with LVEF ≥40%, rather than simply transferring diabetic-CKD findings to a new population.',
    'The primary composite counted total worsening-HF events and cardiovascular death. There were 1083 versus 1283 events: rate ratio 0.84, 95% CI 0.74–0.95, over median follow-up of 32 months.',
    'Total events are not the number of individual patients affected. Do not interpret that composite as an independently established mortality reduction or assume all MRAs have identical trial results.'),
  S('Follow the HF Label Rather Than a Generic MRA Schedule','**For baseline eGFR ==25 to <60==, start ==10 mg daily== and target ==20 mg==; for eGFR ==≥60==, start ==20 mg== and target ==40 mg==.** Do not initiate with potassium ==>5.0 mmol/L== or eGFR ==<25==.',
    'Check potassium and eGFR at four weeks after initiation or dose adjustment, and periodically thereafter. Titration and interruption must follow the HF-specific potassium/eGFR table rather than proceeding automatically to target.',
    'Hyperkalemia, hypotension and renal deterioration need surveillance. Strong CYP3A4 inhibitors and adrenal insufficiency are contraindications; avoid duplicate MRA prescribing and review all potassium-raising treatment. The HF dose framework differs from the diabetic-CKD target, making the indication and baseline renal category essential parts of the prescription.')],['FINEARTS','FINELABEL','ESC2026'])

R['STEPHFPEF']=('STEP-HFpEF randomized trial, 2023','https://doi.org/10.1056/NEJMoa2306963')
R['SUMMIT']=('SUMMIT tirzepatide randomized trial, 2024 online','https://doi.org/10.1056/NEJMoa2410027')
R['NEAT']=('NEAT-HFpEF randomized crossover trial, 2015','https://doi.org/10.1056/NEJMoa1510774')

add('Additional therapy, comorbidity and preserved EF','Obesity-Directed HFpEF Trials Have Different Primary Outcomes',
 'An adult with symptomatic HFpEF and BMI 38 kg/m² asks about semaglutide and tirzepatide. Which comparison of STEP-HFpEF and SUMMIT is most accurate?',
 'STEP-HFpEF demonstrated health-status and weight benefits; SUMMIT also reduced a composite of cardiovascular death or worsening HF',[
 ('Both trials independently established an isolated cardiovascular mortality reduction','STEP-HFpEF primarily assessed health status and weight, and SUMMIT’s composite result does not establish a separate cardiovascular mortality benefit. The endpoints cannot be merged into a universal survival claim.'),
 ('STEP-HFpEF established a reduction in its primary cardiovascular-event endpoint; SUMMIT primarily tested weight loss','STEP-HFpEF’s dual primary endpoints concerned health status and body weight. SUMMIT included a clinical-event composite as well as health status; reversing those trial questions misrepresents the evidence.'),
 ('Both trials had weight change and exercise distance as their two primary endpoints','Weight and functional measures are relevant, but their inclusion does not make them the primary endpoint pair in both trials. Distinguish STEP-HFpEF health-status/weight endpoints from SUMMIT clinical events and health status.')],
 [S('Compare the Trial Questions','**STEP-HFpEF tested weekly semaglutide titrated to 2.4 mg in obesity-associated HFpEF.** At 52 weeks, the between-group KCCQ clinical-summary improvement was 7.8 points and the weight-change difference was −10.7 percentage points.',
    'SUMMIT tested weekly tirzepatide titrated up to 15 mg in HFpEF with obesity. Cardiovascular death or worsening HF occurred in 9.9% versus 15.3%: HR 0.62, 95% CI 0.41–0.95.',
    'The composite advantage should not be presented as an independently proven cardiovascular mortality reduction. The trials support related but nonidentical clinical conclusions.'),
  S('Treat an Appropriate Phenotype','**Obesity can contribute to impaired exercise tolerance, inflammation and circulatory burden in HFpEF.** Treating it complements confirmation of the HF syndrome and management of associated hypertension, AF and sleep apnea.',
    'Trial target doses are reached through gradual escalation; they are not starting doses. Select a product and titration plan using current authorization, tolerability and individual contraindications.',
    'Assess gastrointestinal adverse effects, intake, volume depletion and nutritional or muscle loss during substantial weight reduction. Reassess diuretic needs as status changes. Do not combine the agents as if they were independently proven complementary HF classes. Discuss achievable symptom and weight goals, clinical-event evidence and treatment burden rather than promising cure from obesity reduction alone.')],['STEPHFPEF','SUMMIT','ESC2026'],style='direct')

add('Additional therapy, comorbidity and preserved EF','HFpEF Management Requires Phenotype and Comorbidity Treatment',
 'A patient with established HFpEF, EF 60%, controlled hypertension and AF remains exercise-limited despite tolerated HF-directed medicines. The patient is euvolemic, with resting rate 74/min and an adequate exercise rate response. There is no angina. Which additional approach is most appropriate?',
 'Arrange structured exercise rehabilitation and reassess noncongestive contributors to limitation',[
 ('Add isosorbide mononitrate chiefly to improve daily activity in HFpEF','NEAT-HFpEF did not show better exercise capacity or quality of life and found reduced daily activity with the tested regimen. Routine nitrate use for this purpose is unsupported.'),
 ('Add digoxin to intensify ventricular-rate control','Digoxin can assist rate control when AF rates remain problematic, particularly when other agents are limited. Adequate resting and exercise-rate control are supplied, so additional rate slowing does not address the demonstrated residual limitation.'),
 ('Increase the maintenance loop-diuretic dose','A higher loop dose can help recurrent congestion. The patient is euvolemic, so persistent exercise limitation should prompt rehabilitation and reassessment of other contributors rather than assuming additional sodium removal will improve function.')],
 [S('Match Treatment to the Remaining Limitation','**HFpEF is a heterogeneous syndrome with frequent overlapping contributors to symptoms.** Reassess congestion, pressure, rhythm, renal disease, obesity, anemia/iron status, sleep-disordered breathing and pulmonary disease.',
    'Use indicated SGLT2 treatment and assess eligible MRA or phenotype-directed options under the applicable guideline and label. A drug’s trial population and safety conditions still matter.',
    'Provide exercise and rehabilitation advice suited to functional status, together with nutrition and risk-factor management. Look for a specific treatable etiology such as amyloid or important valve disease when findings suggest it.'),
  S('Interpret Nitrate Evidence Correctly','**NEAT-HFpEF compared escalating isosorbide mononitrate with placebo in a randomized crossover study.** Across tested doses, daily activity was lower with nitrate treatment, without improvement in six-minute walk distance or quality of life.',
    'This does not prohibit a nitrate for a separate appropriate angina indication. It argues against prescribing one routinely as a proven HFpEF exercise-enhancing therapy.',
    'Maintain the lowest diuretic dose that controls congestion and reassess pressure and orthostatic tolerance. AF treatment may address both symptoms and filling, but anticoagulation follows its own indication. Persistent limitation warrants a renewed integrated evaluation rather than an assumption that every symptom is fluid excess or that one normal EF measurement means no cardiac disease remains.')],['NEAT','ESC2026','AHA2022'])

add('Devices and advanced heart failure','Primary-Prevention ICD Assessment After Sustained Medical Treatment',
 'A patient with nonischemic dilated cardiomyopathy remains NYHA II with EF 30% after six months of optimized tolerated HF therapy. QRS is 104 ms. There has been no sustained VT or cardiac arrest. Expected meaningful survival exceeds one year. Under AHA/ACC/HFSA 2022, which device assessment is appropriate?',
 'Offer primary-prevention ICD assessment through shared decision-making',[
 ('Offer CRT-defibrillator assessment','CRT-D combines sudden-death protection with resynchronization, but the narrow QRS of 104 ms and absence of a pacing indication do not support adding routine CRT. The defibrillator indication should be assessed independently.'),
 ('Extend medical treatment for another six months before device assessment','An additional recovery interval may be appropriate when therapy was only recently established or a reversible cause remains active. Six months of optimized tolerated treatment with persistent EF 30% already supports primary-prevention assessment under the named guideline.'),
 ('Use a wearable defibrillator as the long-term prevention strategy','A wearable device may provide selected temporary protection while candidacy or reversibility is clarified. It is not the usual long-term substitute for assessing a permanent ICD in an eligible patient with persistent dysfunction after established treatment.')],
 [S('Separate Primary From Secondary Prevention','**Primary prevention addresses sudden-death risk before a qualifying sustained ventricular arrhythmia occurs.** The AHA 2022 recommendation includes nonischemic DCM with EF ≤35%, NYHA II–III symptoms on chronic therapy and expected meaningful survival >1 year.',
    'Reassess function after a sufficient period of treatment and consider reversible causes. A device decision from an untreated first low-EF measurement can be premature.',
    'Ischemic disease has additional timing considerations after infarction and revascularization. Those waiting periods should not be substituted for the current nonischemic assessment.'),
  S('Discuss Expected Benefit and Competing Risks','**An ICD treats dangerous ventricular tachyarrhythmias but does not prevent every form of death or directly correct pump failure.** Frailty, advanced comorbidity and nonarrhythmic mortality affect net benefit.',
    'Discuss shocks, infection, lead complications, later generator replacement and the patient’s goals. Evaluate pacing needs before choosing a device system.',
    'Guidelines differ in recommendation strength for nonischemic primary prevention: ESC 2026 uses a should-be-considered framework for eligible nonischemic disease, whereas AHA 2022 recommends it in the specified population. Preserve that attribution. A narrow QRS does not rule out an ICD, but helps distinguish defibrillation from a routine CRT indication. Continue HF medicines and follow-up after implantation rather than treating the device as a replacement for medical care.')],['AHA2022','ESC2026'])

add('Devices and advanced heart failure','Wide LBBB Identifies a Strong Resynchronization Indication',
 'A patient remains NYHA III despite optimized HF therapy. LVEF is 28%, rhythm is sinus and ECG shows LBBB with QRS 166 ms. There is no major illness limiting meaningful survival. Which device strategy merits assessment under AHA/ACC/HFSA 2022?',
 'Cardiac resynchronization therapy, with the defibrillator component assessed separately',[
 ('An ICD without resynchronization','An ICD can address sudden-death risk and may be appropriate with a narrow QRS. Here omitting resynchronization overlooks the strong symptomatic wide-LBBB indication that addresses HF burden as well as the separate arrhythmic-risk question.'),
 ('Cardiac contractility modulation','Contractility modulation is considered in selected persistently symptomatic patients without a CRT indication, generally with a different EF and conduction profile. It does not replace established CRT in this patient with EF 28% and LBBB at 166 ms.'),
 ('A wearable cardioverter-defibrillator during an additional recovery interval','A wearable defibrillator may provide selected temporary protection when an enduring device decision is deferred, such as early after a potentially reversible insult. Persistent symptoms after optimized treatment with this wide-LBBB pattern supports definitive CRT assessment rather than routine extension of a bridge strategy.')],
 [S('Use the Complete Electrical and Clinical Pattern','**AHA 2022 indicates CRT for EF ≤35%, sinus rhythm, LBBB and QRS ≥150 ms with NYHA II, III or ambulatory IV symptoms on guideline-directed treatment.** This patient meets the strong-indication pattern.',
    'The effect addresses electrical dyssynchrony and inefficient ventricular contraction. EF alone or an echocardiographic dyssynchrony impression does not reproduce the full selection framework.',
    'Non-LBBB morphology, shorter QRS duration, AF or an indication for substantial ventricular pacing require different recommendation pathways.'),
  S('Choose the System and Assess the Result','**CRT and defibrillation answer related but separate treatment questions.** Decide between pacing-only and defibrillator-capable systems using sudden-death risk, etiology, prognosis and preferences.',
    'Review venous anatomy, lead placement, infection risk and the ability to deliver effective resynchronization. Specialist alternatives may be considered when conventional biventricular pacing is unsuitable.',
    'Continue foundational therapy and follow symptoms, ventricular function and pacing effectiveness after implantation. A nonresponse requires review of capture, rhythm, lead position and alternative causes rather than assuming the initial EF threshold guaranteed benefit. Do not apply this wide-LBBB indication unchanged to a narrow-QRS patient or overlook competing illness that makes a procedure unlikely to provide meaningful recovery.')],['AHA2022','ESC2026'])

R['PACING2023']=('HRS/APHRS/LAHRS cardiac physiologic pacing guideline, 2023','https://doi.org/10.1002/joa3.12872')
R['AHFREFERRAL']=('AHA advanced-HF referral scientific statement, 2021','https://doi.org/10.1161/CIR.0000000000001016')

add('Devices and advanced heart failure','AF Can Prevent Effective Delivery of CRT',
 'A patient with permanent AF, EF 28% and persistent HF symptoms has a CRT system. Interrogation and ECG review show only 82% effective biventricular capture because of conducted AF despite tolerated rate-control treatment. Lead function is satisfactory and frequent ventricular ectopy is excluded. Which next assessment is appropriate?',
 'Evaluate AV-junction ablation to enable near-complete effective biventricular pacing',[
 ('Revise the LV lead position as the first corrective procedure','Lead revision may help when position, thresholds or phrenic stimulation impair resynchronization. Lead function is satisfactory here and the documented limitation is competing conducted AF, so revision does not directly address the identified mechanism.'),
 ('Perform ventricular ectopy ablation to restore pacing delivery','Frequent ventricular ectopy can reduce effective CRT and may justify ablation in selected patients. The stem specifically excludes that mechanism and identifies conducted AF as the source of lost capture.'),
 ('Use AV-delay optimization as the main correction for lost capture','Programming optimization can address selected timing and fusion problems, especially with organized atrial activity. Permanent AF with substantial competing conduction despite tolerated rate control requires assessment of reliable ventricular-rate control rather than relying on an AV-delay adjustment.')],
 [S('Measure Effective Resynchronization','**Clinical benefit depends on effective ventricular capture, not merely implantation or a displayed pacing counter.** AF-related intrinsic conduction, fusion and pseudofusion can reduce actual resynchronization.',
    'Review surface ECG, interrogation and ambulatory assessment where appropriate. Check lead function, programming, ventricular ectopy and rate before assigning the failure solely to AF.',
    'Aim for pacing as close to 100% as possible in this setting. An isolated percentage should be interpreted with how effective capture was determined.'),
  S('Select a Durable Rate and Pacing Strategy','**AV-junction ablation can prevent competing conducted impulses when medication does not permit adequate capture.** This creates pacing dependence and requires a reliable system and informed patient discussion.',
    'The 2023 physiologic-pacing guideline supports biventricular CRT in appropriate AF patients undergoing AV-junction ablation with impaired LV function. Selected conduction-system pacing alternatives require specialist assessment.',
    'Ablating AV conduction does not restore atrial contraction or remove AF-related thromboembolic risk; continue anticoagulation assessment independently. Evaluate rhythm-control options where appropriate, although this vignette concerns established permanent AF and a CRT-delivery problem. After intervention, verify capture and reassess symptoms and ventricular function while continuing indicated HF care rather than assuming the procedural step guarantees recovery.')],['PACING2023','AF2023','AHA2022'])

add('Devices and advanced heart failure','Advanced-HF Referral Should Precede Irreversible Organ Failure',
 'A patient with EF 22% has persistent NYHA III symptoms, two HF admissions in six months, escalating loop requirements and recurrent symptomatic hypotension preventing tolerated doses of prognostic medicines. Renal function is deteriorating but there is no established irreversible organ failure. Which next step is most appropriate?',
 'Refer promptly to an advanced-HF service while continuing stabilization and review of reversible contributors',[
 ('Complete another three-month outpatient medication-titration cycle before referral','Further optimization remains important, but recurrent admissions, worsening kidney function and symptomatic treatment-limiting hypotension indicate a need for specialist review now. Referral can occur alongside optimization rather than await its repeated failure.'),
 ('Start a chronic outpatient inotrope and refer after dependence is established','Chronic inotropes may serve selected bridge or palliative indications after specialist assessment. Inotrope dependence is not a prerequisite for referral and should not be induced as a test of advanced-HF severity.'),
 ('Arrange primary renal evaluation before deciding whether advanced-HF referral is needed','Renal evaluation may be appropriate in parallel, especially with evidence of intrinsic kidney disease. The combined cardiac trajectory already justifies advanced-HF assessment; waiting for a separate renal workup can delay evaluation of reversible cardiorenal dysfunction and treatment options.')],
 [S('Recognize a Pattern Rather Than One EF Value','**Advanced-HF warning signs include recurrent decompensation, persistent severe symptoms, escalating treatment requirements and intolerance of outcome-modifying therapy.** EF contributes information but is not a sufficient definition by itself.',
    'The I NEED HELP framework highlights inotropes, persistent symptoms or high peptides, end-organ dysfunction, low EF, defibrillator shocks, hospitalizations, escalating edema/diuretics, low pressure and inability to tolerate prognostic medicines.',
    'A warning marker prompts consideration of referral; it does not automatically establish eligibility for transplant or an LVAD.'),
  S('Preserve Options Through Timely Assessment','**The advanced-HF team reviews the diagnosis, reversible causes, medical/device optimization and the patient’s goals.** Hemodynamics and exercise assessment can help clarify severity and the feasible pathway.',
    'Potential options include transplantation, durable mechanical support, selected bridging care and symptom-focused treatment. Referral is a consultation, not a commitment to a device or operation.',
    'Assess frailty, nutrition, psychosocial support, comorbidity and organ reversibility early. Palliative care can accompany active treatment and shared decisions rather than being reserved for a failed transplant evaluation. Explain why repeated short-term improvement after diuresis does not erase the worsening long-term trajectory. Continue urgent local management while arranging referral when instability makes travel or delay unsafe.')],['AHFREFERRAL','ACC2024','AHA2022'])

R['ISHLT2024']=('ISHLT cardiac transplant candidate guideline, 2024','https://www.ishlt.org/docs/default-source/standards-guidelines/2024_guideline_careofhtxcandidates.pdf')
R['LVAD2023']=('JACC durable mechanical circulatory support scientific statement, 2023','https://doi.org/10.1016/j.jacc.2023.07.019')

add('Devices and advanced heart failure','CPET Supports Transplant Evaluation Without Acting as a Standalone Listing Rule',
 'An ambulatory patient with advanced HF remains limited despite optimized treatment including a beta blocker. A technically satisfactory maximal CPET shows peak VO2 10.5 mL/kg/min. Which general peak-VO2 threshold does ISHLT 2024 use to support transplant listing assessment in patients taking beta blockers?',
 'At or below 12 mL/kg/min',[
 ('At or below 14 mL/kg/min','The generally higher 14-mL/kg/min threshold is used when beta blockers are not tolerated. Applying it without distinguishing treatment status loses the specific on-treatment framework requested.'),
 ('At or below 10 mL/kg/min','A value this low indicates substantial impairment, but waiting for it would impose a more restrictive boundary than the general on-beta-blocker threshold. The patient’s 10.5 value already supports comprehensive assessment.'),
 ('At or below 16 mL/kg/min','Exercise capacity in this range can still merit evaluation in a concerning clinical trajectory, but 16 is not the cited general absolute threshold supporting listing assessment on beta blockade. Interpret percent-predicted values and other findings separately.')],
 [S('Interpret a Valid Exercise Study','**ISHLT 2024 describes peak VO2 generally ==≤12 mL/kg/min== on beta blockade as supportive of transplant listing assessment.** Without beta blockade, a generally higher supportive threshold of ==≤14 mL/kg/min== is used.',
    'Assess effort, protocol, limiting symptoms and the full gas-exchange pattern. A submaximal effort or important noncardiac limitation can distort interpretation of a low peak value.',
    'A VE/VCO2 slope >35 provides complementary support, particularly with submaximal testing. Percentage-predicted and body-composition-adjusted values can help in selected populations.'),
  S('Integrate the Candidacy Assessment','**Right-heart catheterization characterizes filling pressures, output and pulmonary vascular burden.** Potentially prohibitive pulmonary hypertension requires assessment of reversibility and the appropriate specialist pathway.',
    'Combine functional data with clinical trajectory, admissions, medication tolerance, arrhythmias, organ function and validated prognostic estimates. No single threshold should decide listing independently.',
    'Assess comorbidity, nutrition, frailty, infection/malignancy risk, adherence and support alongside likely benefit. An evaluation may lead to transplantation, mechanical support, continued optimized care or a symptom-focused plan. Explain that a poor test is a reason for timely expert assessment rather than a guarantee of organ allocation or a substitute for informed shared decision-making.')],['ISHLT2024','AHA2022'])

add('Devices and advanced heart failure','An LVAD Requires Adequate Right-Sided Delivery of Blood',
 'A patient with advanced predominantly left-sided HF is being assessed for a durable LVAD. Which finding most directly raises concern that isolated LV support may be insufficient?',
 'Severe persistent RV dysfunction with high right-sided filling pressure despite volume optimization',[
 ('Severe LV systolic dysfunction with a dilated LV and relatively preserved RV function','That pattern can be suitable for isolated LV support when other candidacy requirements are met. Severe LV dysfunction is part of the treatment rationale rather than the specific right-sided limitation asked here.'),
 ('Renal dysfunction that improves when congestion and perfusion are corrected','Reversible cardiorenal dysfunction requires assessment but is different from established irreversible end-organ disease. Improvement can support recovery potential rather than proving isolated LV support is inadequate.'),
 ('Elevated wedge pressure with pulmonary congestion and preserved RV contractile function','High left-sided filling pressure can be a reason to unload the LV. Unlike persistent severe RV failure, this does not itself identify an inability to deliver adequate blood to the LVAD after left-sided support is established.')],
 [S('Assess Both Ventricles','**An LVAD unloads the LV but depends on the RV delivering blood through the pulmonary circulation to fill it.** Severe RV failure can produce persistent congestion and inadequate LVAD preload.',
    'Evaluate RV size/function, TR, right-sided filling pressures, pulmonary vascular load and response to optimization. No isolated echocardiographic number replaces an integrated assessment.',
    'Persistent severe RV dysfunction can require another support strategy or change candidacy; it should not be assumed to resolve automatically after LV unloading.'),
  S('Evaluate the Whole Treatment Burden','**Selection includes organ reversibility, bleeding/thrombotic risk, infection, neurological status and the capacity for long-term care.** Durable support is more than a procedure for a low EF.',
    'Severe irreversible renal, hepatic or neurological disease can make benefit unlikely, whereas potentially reversible congestion-related dysfunction requires specialist assessment rather than automatic exclusion.',
    'Review anticoagulation feasibility, driveline care, power/device management, adherence and social support. Counsel about bleeding, stroke, infection, pump-related problems and right-HF risk. Compare the feasible support configuration with transplant and medical options in the context of the patient’s goals. Timely referral before shock and irreversible injury preserves the opportunity to assess and optimize these factors rather than forcing a decision during collapse.')],['LVAD2023','AHA2022','ESC2026'])

add('Devices and advanced heart failure','Support Intent Must Be Defined and Reassessed',
 'An otherwise suitable advanced-HF patient is not currently transplant-listable because pulmonary vascular resistance remains elevated. The specialist team selects durable LV support to unload the LV and reassess whether the barrier becomes reversible. Which support intent best describes this plan?',
 'Bridge to candidacy',[
 ('Bridge to transplantation','This usually describes support for an accepted transplant candidate awaiting an organ. Here a current eligibility barrier must first be reassessed before listing can be established.'),
 ('Destination therapy','Destination therapy denotes intended long-term support when transplantation is not the planned endpoint. The stated plan instead seeks to change a potentially reversible candidacy limitation.'),
 ('Bridge to recovery','Recovery intent seeks sufficient native cardiac improvement to permit support withdrawal. The principal stated objective is to improve transplant eligibility, not anticipated device explantation after myocardial recovery.')],
 [S('Define the Destination Before Implantation','**Bridge to candidacy addresses a potentially modifiable barrier to transplantation.** The team must specify what is expected to improve, how it will be measured and when reassessment will occur.',
    'LV unloading can reduce pulmonary venous pressure and may improve a reversible pulmonary vascular component. Improvement is not guaranteed, and persistent prohibitive disease can change the subsequent plan.',
    'Do not assume that a patient is transplant-eligible merely because support has been implanted or a pressure measurement improves once.'),
  S('Distinguish Related Strategies','**Bridge to transplant, candidacy, decision and recovery describe different clinical intentions.** Temporary bridge-to-decision support can allow stabilization and assessment when prognosis or eligibility remains uncertain.',
    'Destination therapy can be appropriate when durable support offers meaningful benefit and transplantation is not planned. The treatment burden still includes long-term follow-up, anticoagulation assessment and device-related risk.',
    'Intent can evolve with organ function, complications, patient preferences and transplant eligibility. Discuss realistic alternative pathways before implantation, including what will happen if the hoped-for barrier does not resolve. Repeat hemodynamic, RV and end-organ assessment as indicated rather than retaining an outdated label. A named bridge is a monitored clinical plan with an endpoint, not an assurance that transplantation, recovery or permanent support will ultimately be feasible.')],['LVAD2023','ISHLT2024','ESC2026'])

add('Devices and advanced heart failure','Palliative Care Can Accompany Transplant or LVAD Evaluation',
 'A patient with advanced HF undergoing transplant evaluation has refractory breathlessness, anxiety and caregiver strain. The patient wants continued assessment for life-prolonging treatment. Which approach is most appropriate?',
 'Integrate palliative symptom and communication support alongside active HF and transplant care',[
 ('Complete transplant candidacy assessment before adding specialist symptom support','A definitive candidacy decision can inform later goals, but difficult symptoms and caregiver strain need attention during evaluation. Concurrent support does not prejudice transplant assessment or require abandoning life-prolonging treatment.'),
 ('Arrange hospice assessment as the primary response to refractory breathlessness','Hospice may be appropriate when prognosis and preferences align with that model of care. The patient wants active evaluation and no hospice eligibility or preference is supplied; specialist palliative support is the better matched concurrent intervention.'),
 ('Continue HF treatment and arrange isolated psychological counseling','Psychological counseling can help anxiety, but it does not by itself address refractory physical symptoms, caregiver burden and complex treatment communication. An integrated palliative approach can coordinate these needs alongside the ongoing cardiac evaluation.')],
 [S('Provide Support Throughout Serious Illness','**Palliative care addresses physical symptoms, distress, communication and goals alongside disease-directed HF treatment.** It does not require withdrawal of medicines, devices or transplant assessment.',
    'AHA/ACC/HFSA 2022 recommends supportive and palliative approaches across HF care. Specialist involvement is particularly useful for difficult symptoms, complex decisions or substantial caregiver distress.',
    'Clarify what matters to the patient, what outcomes are acceptable and which burdens are tolerable. Discuss uncertainty without presenting a device or transplant as a guaranteed solution.'),
  S('Plan for Decisions Before a Crisis','**Review future scenarios with the patient and chosen supporters while decision-making capacity and time permit.** Document preferences and revisit them as the clinical trajectory changes.',
    'Discuss possible ICU treatment, temporary support, durable devices, transplantation and the option to decline burdensome interventions. An ICD shock-deactivation discussion is distinct from turning off pacing or stopping all cardiac care.',
    'Treat congestion and other reversible contributors to breathlessness, and individualize symptom management with attention to renal function, cognition and adverse effects. Hospice assessment may become appropriate when prognosis and preferences align, but palliative care need not wait for that point. Coordinate the HF, transplant and palliative teams so the patient receives one coherent plan rather than conflicting messages about whether symptom support implies abandonment of active treatment.')],['AHA2022','AHFREFERRAL'])

R['ACCHOSP2024']=('ACC hospitalized HF consensus pathway, 2024','https://doi.org/10.1016/j.jacc.2024.06.002')

add('Decompensated heart failure','Treat Decompensation While Seeking Its Urgent Precipitant',
 'A patient with chronic HF presents with abrupt dyspnea, hypoxemia and congestion. There has been no recent weight gain, and medication adherence is confirmed. Which initial diagnostic strategy is most appropriate alongside respiratory and hemodynamic stabilization?',
 'Rapidly assess for time-critical precipitants using ECG, focused cardiac imaging and clinically directed investigations',[
 ('Prioritize CT pulmonary angiography before cardiac evaluation','CTPA is appropriate when pulmonary embolism is sufficiently suspected and the patient can undergo testing. Abrupt dyspnea alone does not establish it as the first test over rapid ECG and bedside cardiac assessment for several immediately treatable causes.'),
 ('Proceed directly to coronary angiography before ECG and focused imaging','Urgent angiography is essential for an appropriate coronary indication, but the generic presentation does not establish coronary occlusion. Immediate ECG and focused assessment help identify that pathway as well as rhythm, valve and other causes.'),
 ('Use serial natriuretic peptides and diuretic response as the main etiological assessment','Peptides and response can support a congestion assessment but do not identify an acute coronary, rhythm or mechanical precipitant. A favorable diuretic response cannot substitute for the early search for causes requiring specific treatment.')],
 [S('Search for Causes That Change Immediate Treatment','**The CHAMPIT framework highlights coronary syndromes, hypertensive emergencies, arrhythmias, mechanical lesions, pulmonary embolism, infection and tamponade.** These require cause-directed treatment beyond a generic diuretic prescription.',
    'Obtain ECG and timely echocardiographic or focused imaging assessment, with troponin, renal/electrolyte testing and additional studies driven by the presentation.',
    'Suspected embolism, infection or acute valve/mechanical disease needs an appropriate specific pathway. Do not order every possible test indiscriminately or assume that elevated troponin alone proves coronary occlusion.'),
  S('Connect Phenotype With the Precipitant','**Pulmonary fluid redistribution can occur rapidly, particularly with hypertension or acute changes in cardiac loading.** It need not be preceded by prolonged peripheral edema or several kilograms of weight gain.',
    'Assess oxygenation, respiratory effort, blood pressure, perfusion and congestion repeatedly. Diuresis, vasodilators or circulatory support depend on the physiological state and underlying cause.',
    'Review adherence, recent drugs, sodium intake, renal deterioration and other slower contributors once urgent threats are being addressed. A favorable response to initial support does not establish the etiology or remove the need to identify a reversible trigger. Document the likely cause and prevention plan before discharge so recurrent events are not treated as unexplained inevitable HF progression.')],['ESC2021','ACCHOSP2024','ESC2026'])

add('Decompensated heart failure','Congestion and Perfusion Are Separate Assessment Axes',
 'A patient with decompensated HF has elevated JVP, edema and pulmonary crackles. Extremities are warm, mentation is normal, lactate is 1.3 mmol/L and urine output is preserved. BP is 104/68 mmHg. Which bedside profile best fits?',
 'Congested with preserved perfusion: warm–wet',[
 ('Congested with hypoperfusion: cold–wet','Congestion is present, but the supplied peripheral, cognitive, metabolic and urine findings do not support hypoperfusion. A modest pressure alone does not establish a cold profile.'),
 ('Euvolemic with hypoperfusion: cold–dry','This label misses both the clear congestion and the reassuring perfusion findings. Low output and low pressure are not interchangeable with the actual examination.'),
 ('Euvolemic with preserved perfusion: warm–dry','The perfusion description fits, but elevated JVP, edema and crackles establish a congested rather than dry presentation.')],
 [S('Assess the Two Axes Independently','**Warm/cold describes clinical perfusion, while wet/dry describes congestion.** These labels guide an initial physiological assessment rather than serving as a complete diagnosis.',
    'Congestion assessment includes JVP, edema, orthopnea, lung findings and appropriate imaging. Perfusion assessment includes temperature, mentation, urine output, capillary refill and metabolic/organ trends.',
    'Preserved blood pressure can coexist with hypoperfusion, and a relatively low pressure can coexist with adequate perfusion. Integrate the findings rather than substituting one pressure cutoff.'),
  S('Choose Treatment and Reassess the Trajectory','**A warm–wet presentation generally prioritizes decongestion and treatment of the precipitant.** Vasodilators require an appropriate pressure and clinical setting; inotropes are not routine treatment for congestion with adequate perfusion.',
    'A cold profile requires urgent evaluation of low-output and alternative shock mechanisms. A dry label does not by itself prove a need for a large fluid bolus.',
    'Repeat bedside and laboratory assessment during treatment, because the profile can change. Clinical categories may be uncertain in complex right-sided disease, mixed shock or discordant findings; targeted invasive hemodynamics can clarify selected consequential uncertainty. The supplied normal lactate supports the overall assessment but does not independently exclude every early perfusion problem. Treat the patient’s integrated trajectory rather than retaining an admission label despite new deterioration.')],['ACCHOSP2024','AHA2022'])

add('Decompensated heart failure','Early NIV for Hypoxemic Cardiogenic Pulmonary Edema',
 'A patient with cardiogenic pulmonary edema is alert and cooperative, with respiratory rate 34/min, SpO2 84% on room air and BP 168/96 mmHg. There is no vomiting, inability to protect the airway or shock. Which respiratory strategy is most appropriate alongside cause-directed treatment?',
 'Give oxygen and promptly initiate monitored noninvasive positive-pressure ventilation',[
 ('High-flow nasal oxygen as the initial support strategy','High-flow oxygen can help selected hypoxemic patients, particularly when a mask is poorly tolerated. In this cooperative patient with severe cardiogenic pulmonary edema and substantial work of breathing, early NIV supplies established positive-pressure support rather than oxygen delivery alone.'),
 ('Endotracheal intubation with invasive ventilation','Intubation is appropriate with impaired airway protection, exhaustion, progressive respiratory failure despite initial support or severe instability. None is supplied; a closely monitored NIV trial avoids an immediate invasive procedure while retaining a clear rescue pathway.'),
 ('Controlled oxygen by face mask with medical decongestion','Controlled oxygen and diuresis can suffice for milder edema without marked distress. Respiratory rate 34/min and saturation 84% identify a need for prompt ventilatory assistance rather than relying on oxygen and the later diuretic response alone.')],
 [S('Select Support From Respiratory and Circulatory Status','**NIV can improve oxygenation and reduce work of breathing in suitable cardiogenic pulmonary edema.** CPAP or bilevel support requires an experienced monitored setting with rapid reassessment.',
    'ESC 2021 identifies respiratory distress with rate >25/min and SpO2 <90% as a setting for early consideration of noninvasive positive pressure. The supplied values clearly meet that pattern.',
    'Oxygen treats hypoxemia; routine oxygen in a patient with adequate saturation is a different question. Titrate according to oxygenation and any relevant risk of hypercapnia.'),
  S('Recognize Failure and Contraindications','**A NIV trial must not delay intubation when the patient deteriorates.** Assess consciousness, airway protection, respiratory fatigue, gas exchange, pressure and response within the early treatment period.',
    'Vomiting, major aspiration risk, inability to cooperate or protect the airway, and severe instability can make NIV unsafe or inadequate. Positive pressure can reduce venous return and requires particular caution in hypotension or RV-dependent circulation.',
    'Treat the cardiac precipitant and use appropriate diuresis or vasodilation in parallel. Improvement in saturation alone does not establish that the work of breathing or hemodynamics have normalized. Escalate for progressive respiratory failure despite oxygen/NIV, and prepare for the circulatory effects of induction and invasive ventilation rather than treating airway management as separate from HF physiology.')],['ESC2021','ACCHOSP2024'])

add('Decompensated heart failure','Use Prior Loop Exposure to Plan Initial IV Decongestion',
 'A congested, adequately perfused patient is admitted despite taking oral furosemide 40 mg twice daily. The team selects an initial total IV dose equal to twice the home total daily oral dose, with subsequent response-guided adjustment. Which prescription matches that plan?',
 'Furosemide 80 mg IV twice daily initially',[
 ('Furosemide 40 mg IV twice daily initially','This supplies eighty milligrams IV daily, equal to the home total daily oral dose rather than the chosen twofold strategy. It can represent a different starting intensity, but does not match the specified plan.'),
 ('Furosemide 80 mg IV once daily initially','This also totals eighty milligrams daily. The route change does not make it the selected 160-milligram daily IV regimen.'),
 ('Furosemide 40 mg IV once daily initially','This provides only half the home total daily dose and one quarter of the specified IV daily amount. It underestimates the chosen starting strategy in a chronically exposed congested patient.')],
 [S('Calculate the Planned Initial Dose','**The home total is 40 mg twice daily = 80 mg orally per day.** A selected twofold IV strategy therefore supplies 160 mg IV per day, divided here as 80 mg twice daily.',
    'The ACC 2024 hospitalized-HF pathway describes initial IV treatment at approximately one to 2.5 times the total daily oral furosemide-equivalent dose in previously treated patients.',
    'This is an initial decongestion strategy, not a claim that oral and IV furosemide have identical bioavailability. It must also not be confused with a universal fixed dose for every patient.'),
  S('Assess Early Response and Safety','**A correct initial calculation does not guarantee an adequate response.** Record urine output, symptoms, weight, pressure, congestion and renal/electrolyte trends.',
    'Early spot urine sodium can help assess natriuresis within a structured protocol. Do not wait until the next day to recognize an inadequate response in a persistently congested patient.',
    'Adjust promptly for response, prior exposure, renal function and tolerance; an inadequate loop effect may require dose escalation before selected combination therapy. A smaller dose can be appropriate in a different physiological setting, while shock or severe depletion changes the treatment priorities. Avoid assuming that continuous infusion is mandatory or prognostically superior to effective intermittent dosing. Transition to an individualized oral maintenance plan after sufficient decongestion rather than retaining the admission IV strategy indefinitely.')],['ACCHOSP2024','AHA2022'],calculation=True)

R['ADVOR']=('ADVOR randomized trial, 2022','https://doi.org/10.1056/NEJMoa2203094')
R['ADVORRENAL']=('ADVOR prespecified renal analysis, 2023','https://doi.org/10.1093/eurheartj/ehad557')

add('Decompensated heart failure','Persistent Congestion After Adequate Loop Escalation Warrants Selected Combination Therapy',
 'An adequately perfused patient remains markedly congested despite high-dose IV loop escalation with confirmed administration. Two-hour urine sodium remains 28 mmol/L and urine output is poor. BP is 108/68 mmHg, sodium 138 mmol/L and eGFR 36 mL/min/1.73 m². No combination diuretic has been tried. Which next strategy is most appropriate?',
 'Add a thiazide-type diuretic with close electrolyte and renal surveillance',[
 ('Proceed directly to extracorporeal ultrafiltration','Ultrafiltration can be considered for selected congestion refractory to escalated pharmacological treatment or a separate dialysis indication. Here complementary diuretic blockade has not yet been tried and no urgent kidney-replacement indication is supplied.'),
 ('Add tolvaptan as the preferred natriuretic adjunct','Tolvaptan promotes electrolyte-free water excretion and may help selected hypervolemic hyponatremia. Sodium is normal here, and the immediate problem is inadequate sodium removal rather than a specific need for aquaresis.'),
 ('Change to oral torsemide as the main escalation step','Torsemide can improve predictable oral delivery when outpatient absorption or adherence is problematic. Confirmed high-dose intravenous loop exposure already bypasses oral absorption, so an oral formulation switch does not address the demonstrated inadequate IV response.')],
 [S('Confirm an Inadequate Response','**Early urine output and sodium excretion help identify ineffective decongestion.** The ACC 2024 pathway notes that spot urine sodium <50 mmol/L at two hours correlates with a poor response and supports considering escalation.',
    'Other protocols use 50–70 mmol/L and urine-output targets; use the specified local algorithm rather than treating one threshold as a universal outcome endpoint.',
    'Review dose delivery, kidney function, renal perfusion, NSAID exposure, intake and urinary obstruction. A low measured output should be verified before attributing it entirely to nephron adaptation.'),
  S('Add a Complementary Site of Action','**A thiazide-type agent such as metolazone can overcome compensatory distal sodium reabsorption.** An initial oral 2.5–5 mg dose is a common selected approach, adjusted to response and the clinical protocol.',
    'Combination treatment can cause substantial hypokalemia, hyponatremia, magnesium loss and renal deterioration. Monitor laboratory values, pressure, output and volume status more closely than with stable maintenance treatment.',
    'Acetazolamide provides a proximal alternative in selected settings; it is not pharmacologically identical to a thiazide. Continue reassessing congestion and perfusion and reduce excess exposure after the target is reached. Refractory disease or uncertain hemodynamics may require specialist invasive assessment or another strategy. More natriuresis does not by itself establish a mortality advantage for every escalation protocol.')],['ACCHOSP2024','AHA2022'])

add('Decompensated heart failure','ADVOR Demonstrated Earlier Decongestion With Added Acetazolamide',
 'Which statement accurately describes ADVOR when considering acetazolamide in hospitalized HF with volume overload?',
 'IV acetazolamide 500 mg daily added to standardized loop treatment improved successful decongestion within three days',[
 ('IV acetazolamide 500 mg daily reduced the primary endpoint of death or HF readmission at three months','The dose matches ADVOR, but the primary endpoint was successful decongestion within three days. The trial did not establish a significant reduction in the later composite of death or HF readmission.'),
 ('The trial directly established the same effect in patients already taking an SGLT2 inhibitor','SGLT2 inhibitor treatment was an exclusion, so the original randomized result does not directly test that combination. Contemporary combination decisions require additional evidence and clinical assessment.'),
 ('Oral acetazolamide 250 mg twice daily added to loop treatment improved three-day decongestion','Oral acetazolamide has clinical uses and carbonic-anhydrase effects, but this was not the randomized ADVOR regimen. The trial tested 500 mg intravenously once daily, so route and regimen cannot be silently substituted.')],
 [S('Intervention and Primary Result','**Acetazolamide inhibits carbonic anhydrase and reduces proximal sodium/bicarbonate reabsorption.** ADVOR tested 500 mg IV once daily for the early three-day treatment period with standardized IV loop therapy.',
    'Successful decongestion occurred in 42.2% versus 30.5%: risk ratio 1.46, 95% CI 1.17–1.82. This was an early clinical congestion endpoint.',
    'Retain the population, background loop regimen and endpoint. A favorable decongestion result is not interchangeable with proof of reduced death or later HF readmission.'),
  S('Eligibility and Monitoring Matter','**The trial excluded SBP <90 mmHg, eGFR <20 and ongoing SGLT2 inhibitor treatment.** These exclusions limit direct extrapolation, including to modern patients already receiving multiple proximal-active therapies.',
    'Monitor bicarbonate, sodium, potassium, renal function and volume status. Acetazolamide can produce metabolic acidosis; baseline acid–base state and product-specific contraindications require review.',
    'Subsequent renal analyses identified more treatment-period worsening renal function with acetazolamide, reinforcing the need to distinguish transient laboratory change from persistent injury and to assess decongestion together with safety. The original short course should not become indefinite chronic therapy through an unclear handover. Choose adjunctive treatment according to the patient’s physiology, response and monitoring capacity rather than assuming every congested admission requires the same combination.')],['ADVOR','ADVORRENAL','ACCHOSP2024'],style='direct')

R['NTGLABEL']=('Nitroglycerin injection prescribing information','https://www.dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9453bd8b-5d54-5dc8-e053-2995a90a95b2')

add('Decompensated heart failure','Titrated Vasodilation for Hypertensive Pulmonary Edema',
 'A patient with cardiogenic pulmonary edema remains markedly hypertensive at 190/110 mmHg while oxygen/NIV support is initiated. Perfusion is preserved. There is no recent PDE5 inhibitor use, riociguat treatment, severe outflow obstruction or other nitrate contraindication. Which adjunctive strategy is most appropriate?',
 'Titrated intravenous nitroglycerin with close pressure and clinical monitoring',[
 ('Intravenous labetalol titrated to pressure response','Labetalol is useful in selected hypertensive emergencies, including some aortic or neurological presentations. Acute pulmonary edema from LV failure creates concern about negative inotropy and is better matched to a titratable vasodilator.'),
 ('Oral isosorbide mononitrate with subsequent reassessment','A long-acting nitrate may treat chronic angina, but its oral onset and prolonged effect are less suited to rapidly changing severe pulmonary edema than a closely titrated intravenous infusion.'),
 ('Intravenous furosemide without an initial vasodilator','IV loop treatment is appropriate when volume overload contributes and may be sufficient in less hypertensive congestion. At 190/110 mmHg with acute edema, withholding a feasible titratable vasodilator overlooks immediate afterload and preload reduction while decongestion proceeds.')],
 [S('Address Pressure-Related Redistribution','**Markedly elevated afterload and venous pressure can cause rapid pulmonary fluid redistribution.** Vasodilation can improve loading conditions while respiratory support and appropriate decongestion proceed.',
    'ESC 2021 permits IV vasodilator consideration in acute HF with SBP >110 mmHg. That boundary is a selection aid, not a target to reduce every patient immediately to the same pressure.',
    'Nitroglycerin produces venodilation and, at higher doses, arterial effects. This treatment is directed at the current physiology rather than a claim of proven long-term survival benefit.'),
  S('Titrate Within a Monitored Protocol','**The cited infusion label starts at 5 micrograms/min using nonadsorptive tubing and initially increases by 5 micrograms/min every three to five minutes according to response.** Escalation protocols can differ in severe hypertensive presentations.',
    'Monitor pressure, respiratory effort, symptoms and perfusion continuously or frequently according to acuity. Do not persist with vasodilation as hypotension or hypoperfusion develops.',
    'Check recent PDE5 exposure and avoid combination with riociguat. Preload-dependent RV disease, important obstruction or hypovolemia can alter safety. Treat the precipitant, including a coronary or acute mechanical cause when present. A falling pressure without improved breathing or perfusion requires reassessment rather than automatic dose escalation. The drug complements respiratory support and volume assessment; it does not replace either.')],['NTGLABEL','ESC2021','ACCHOSP2024'])

add('Decompensated heart failure','Persistent Congestion Changes the Interpretation of a Small Creatinine Rise',
 'During IV diuresis, creatinine rises from 1.3 to 1.6 mg/dL. The patient remains warm, with BP 118/72 mmHg, preserved urine output and improving dyspnea, but JVP and edema remain elevated. There is no sepsis, nephrotoxin exposure or obstruction. Which plan is most appropriate?',
 'Continue carefully monitored decongestion while reassessing renal function and perfusion',[
 ('Pause IV diuresis for twenty-four hours and resume after creatinine improves','A pause can be appropriate with evidence of depletion, progressive injury or hemodynamic compromise. Here substantial congestion remains with preserved pressure and output; an isolated modest rise does not justify routinely interrupting effective decongestion.'),
 ('Switch immediately from diuretics to ultrafiltration','Ultrafiltration can be considered in selected refractory congestion or when kidney-replacement indications arise. The patient is responding to diuresis and no such indication is supplied; a small creatinine increase alone does not establish superiority of extracorporeal removal.'),
 ('Add low-dose dobutamine to improve renal perfusion before further diuresis','Inotropic support may be necessary in low-output hypoperfusion. Warm extremities, preserved urine output and stable pressure do not identify that problem here, and routine inotropy adds risk without resolving the actual congestion-versus-filtration assessment.')],
 [S('Distinguish a Laboratory Change From Its Cause','**Creatinine reflects filtration and is influenced by hemodynamics, congestion and treatment.** A modest increase during effective diuresis can occur without proving intrinsic renal injury.',
    'Review the trend, urine output, pressure, perfusion and volume findings. Venous congestion itself can impair kidney function, while excessive diuresis or shock can produce a different renal problem.',
    'The current persistent JVP elevation and edema support continuing the decongestion assessment; they do not guarantee that every subsequent rise can be safely ignored.'),
  S('Balance Effective Relief With Renal Safety','**AHA 2022 cautions against prematurely stopping diuresis for small creatinine changes when congestion remains.** Avoid treating the laboratory value as the sole therapeutic target.',
    'Repeat electrolytes and renal measurements, reassess dose response and look again for infection, nephrotoxins, obstruction or depleted intravascular volume if the course changes.',
    'Progressive creatinine elevation, falling output, hypotension, rising lactate or new electrolyte/acid–base problems require a revised plan. Selected uncertain cases need hemodynamic assessment. Before discharge, assess the full congestion burden, oral regimen, stability and follow-up rather than accepting temporary relief of pulmonary symptoms as complete recovery. This differs from applying an ACEi/ARB initiation threshold: decongestion requires its own integrated physiological assessment.')],['AHA2022','ACCHOSP2024'])

R['OPTIME']=('OPTIME-CHF randomized milrinone trial, 2002','https://jamanetwork.com/journals/jama/fullarticle/194768')
R['STRONGHF']=('STRONG-HF randomized trial, 2022','https://doi.org/10.1016/S0140-6736(22)02076-1')

add('Decompensated heart failure','Congestion Alone Does Not Establish an Inotrope Indication',
 'A patient with EF 20% is hospitalized with congestion but remains warm, alert and adequately perfused, with preserved urine output and stable pressure. IV diuretic adjustment is underway. Which treatment strategy is most appropriate?',
 'Continue response-guided IV decongestion without adding an inotrope',[
 ('Add a short milrinone infusion to facilitate decongestion','Milrinone may support selected low-output states, but OPTIME-CHF did not support routine use when inotropes were not essential and found more hypotension and atrial arrhythmias. Low EF alone does not identify a favorable indication.'),
 ('Add a low-dose dobutamine infusion to augment forward flow','Dobutamine can support documented low-output hypoperfusion. The supplied clinical findings indicate preserved tissue perfusion, so increasing contractility introduces arrhythmic and ischemic risks without an established physiological need.'),
 ('Add a low-dose dopamine infusion to augment renal response','Dopamine may be considered in selected circulatory settings, but a renal-dose strategy is not established routine therapy for a perfused congested HF patient. Verify diuretic response and adjust decongestion rather than inferring renal hypoperfusion from low EF.')],
 [S('Identify the Hemodynamic Need','**Inotropes increase contractile support but have risks that differ from diuretic and foundational therapy.** A severely reduced EF is not equivalent to current tissue hypoperfusion.',
    'Assess pressure, mentation, peripheral circulation, urine output, lactate and end-organ trends. Inotropes may be required for selected cardiogenic shock or low-output states under monitored specialist care.',
    'Selected advanced-HF bridging or palliative use is a separate indication requiring explicit goals; it should not be inferred from every admission.'),
  S('Interpret Routine-Use Evidence','**OPTIME-CHF tested short-term milrinone in hospitalized systolic HF where inotropes were not considered essential.** It did not improve the principal hospitalization outcome and increased sustained hypotension and new atrial arrhythmias.',
    'Do not extend that negative routine-use result into a prohibition against lifesaving support in shock. The population and immediate physiological need differ.',
    'Continue response-guided decongestion and precipitant treatment in this warm patient. If perfusion deteriorates, re-evaluate the phenotype and escalation pathway promptly. An inotrope trial is not a substitute for identifying an untreated mechanical lesion, ischemia, infection or inadequate diuretic delivery. Document why support is started, the intended endpoint and the reassessment plan whenever a true indication develops.')],['OPTIME','AHA2022','ACCHOSP2024'])

add('Decompensated heart failure','STRONG-HF Tested Rapid Optimization Together With Close Follow-Up',
 'A patient is stable after an HF admission but remains below tolerated target doses of oral therapy. Which discharge strategy most closely reflects the benefit demonstrated in STRONG-HF?',
 'Begin monitored optimization before discharge and arrange rapid tolerated titration with early repeated clinical and laboratory reviews',[
 ('Aim for target doses over three months with monthly review beginning at four weeks','This may resemble a slower outpatient titration plan and can be individualized when needed. It does not reproduce STRONG-HF’s early high-intensity schedule, which targeted recommended doses within two weeks with earlier repeated review.'),
 ('Maintain discharge doses until a six-week visit, using interim telephone symptom checks','Telephone support can improve continuity, but symptom checks without the studied early clinical/laboratory titration process do not reproduce the trial intervention. Important laboratory intolerance may develop before symptoms identify it.'),
 ('Use weekly NT-proBNP testing to determine whether medication titration is necessary','Biomarker trends can inform assessment, but STRONG-HF tested an organized optimization and follow-up bundle rather than biomarker testing as the sole trigger. The evidence does not isolate benefit from serial peptide measurement alone.')],
 [S('Population, Intervention and Outcome','**STRONG-HF randomized eligible stabilized HF admissions not already receiving full-dose treatment to usual care or high-intensity care.** The latter aimed for recommended doses within two weeks with four early follow-up visits.',
    'HF readmission or all-cause death by 180 days occurred in 15.2% versus 23.3%; adjusted risk ratio 0.66, 95% CI 0.50–0.86.',
    'This was a composite clinical endpoint for an organized treatment strategy. It does not establish an identical isolated mortality effect or a benefit from one laboratory test alone.'),
  S('Reproduce the Safety Process','**Assess congestion, pressure, pulse, renal function, electrolytes and treatment tolerance before and after dose changes.** The studied early visits were at approximately one, two, three and six weeks.',
    'The original strategy emphasized RAS inhibition, beta blockade and MRA titration; it should not be relabeled as a randomized test of every possible modern four-drug sequence.',
    'Integrate current indicated treatment, including SGLT2 therapy, while respecting individual contraindications. Give a clear oral diuretic plan, medication reconciliation, warning signs and a contact route. Rapid titration means actively reaching tolerated treatment with surveillance, not forcing target doses through symptomatic hypotension or unsafe laboratory values. Tailor timing when frailty, instability or access barriers prevent the exact trial schedule, and document how monitoring will be delivered.')],['STRONGHF','ACCHOSP2024','ACC2024'])

R['ACCSHOCK2025']=('ACC cardiogenic shock consensus guidance, 2025','https://doi.org/10.1016/j.jacc.2025.02.018')
R['SCAI2026']=('SCAI shock classification expert consensus update, 2026','https://www.scai.org/publications/clinical-documents/2026-scai-shock-classification-expert-consensus-update-refined')
R['SCAICHECK']=('SCAI 2026 bedside classification checklist','https://www.scai.org/sites/default/files/2026-11/SCAI_SHOCK_2026_Bedside_Checklist.pdf')

add('Cardiogenic shock','Preserved Arterial Pressure Does Not Exclude Cardiogenic Hypoperfusion',
 'A patient with severe LV dysfunction has BP 108/74 mmHg but develops cool mottled extremities, confusion, oliguria and rising lactate to 4.5 mmol/L. Focused evaluation supports low cardiac output without major hemorrhage or infection. Which interpretation is most appropriate?',
 'Normotensive cardiogenic hypoperfusion requiring urgent shock assessment',[
 ('Decompensated HF with preserved tissue perfusion','A maintained systolic pressure can coexist with low forward flow when vascular resistance rises. Confusion, oliguria, cold mottling and increasing lactate contradict preserved tissue perfusion despite the numerical pressure.'),
 ('Predominantly hypovolemic shock with compensatory vasoconstriction','Hypovolemia can produce a cold low-output pattern and requires assessment when fluid loss or low filling is plausible. The focused evaluation instead supports ventricular pump failure; low urine output alone does not establish a volume deficit.'),
 ('Predominantly distributive shock associated with occult infection','Infection can cause lactate elevation and coexist with myocardial dysfunction, but no major infectious contributor is identified here. The cardiac assessment and cold low-output pattern favor a cardiogenic mechanism; lactate alone cannot assign the etiology.')],
 [S('Recognize Normotensive Shock','**Cardiogenic shock reflects cardiac failure with inadequate tissue perfusion, not merely a low cuff pressure.** High systemic vascular resistance can maintain pressure while forward flow is insufficient.',
    'The ACC 2025 guidance explicitly recognizes normotensive cardiogenic shock. The SCAI 2026 update also emphasizes looking for hypoperfusion when pressure is preserved.',
    'Assess capillary refill, temperature, mentation, urine output, lactate and organ trends together. A single abnormal marker is less specific than this coherent clinical pattern.'),
  S('Escalate According to Physiology and Cause','**Activate monitored specialist shock assessment and investigate a reversible cardiac precipitant.** ECG, echo and targeted hemodynamics can identify ventricular, valvular or mechanical contributors.',
    'Exclude important hypovolemia, obstruction, infection and mixed vasodilation. Do not give a routine large fluid load solely because urine output is low in a patient with ventricular failure.',
    'Select vasoactive or mechanical support from the failing chamber, pressure, perfusion and trajectory rather than pressure alone. Repeat assessment after each intervention and do not label the patient stable merely because the numerical MAP appears acceptable. Early recognition can permit transfer or definitive treatment before the compensatory vascular response fails and profound hypotension develops.')],['ACCSHOCK2025','SCAI2026'])

add('Cardiogenic shock','SCAI Stage D Describes Failure of Initial Support to Restore Perfusion',
 'A patient with cardiogenic shock remains hypoperfused after initial support. Lactate rises from 3 to 5 mmol/L, urine output falls and vasoactive requirements escalate. There is no impending arrest or near-pulseless collapse. Which SCAI 2026 stage best describes the current trajectory?',
 'Stage D: deteriorating',[
 ('Stage B: beginning shock','Stage B has hemodynamic instability without hypoperfusion. This patient has established and worsening tissue-perfusion abnormalities despite initial treatment.'),
 ('Stage C: classic shock without evidence of progression','Stage C describes hypoperfusion requiring intervention, but failure of the initial strategy with persistent or worsening perfusion supports progression to D rather than retaining the original stage.'),
 ('Stage E: extremis','Stage E concerns acute or impending circulatory collapse. The supplied deterioration is serious but lacks the collapse phenotype specified for extremis; escalation of treatment alone does not establish E.')],
 [S('Classify the Current State and Trajectory','**The SCAI 2026 update emphasizes clinical state rather than assigning a stage from a device name or a medication count alone.** Stage D indicates that initial support has failed to restore perfusion.',
    'Rising lactate, worsening renal function and increasing support requirements are evidence of deterioration. Reassess what the support is achieving, not merely whether it has been started.',
    'A patient can improve or worsen over time; timestamp repeated staging. Etiology, phenotype and arrest-related neurological risk add context beyond the A–E label.'),
  S('Use Staging to Trigger Reassessment','**Failure of initial support requires urgent review of cause, adequacy of therapy and escalation options.** Check ventricular phenotype, congestion, pressure, gas exchange and potentially correctable complications.',
    'Consider shock-team transfer and targeted invasive assessment when they can guide treatment, without delaying lifesaving intervention. Assess whether the intended destination is recovery, a decision, durable support or transplantation.',
    'The arrest modifier addresses concern for anoxic brain injury and is not synonymous with every stage E presentation. Do not treat a recovering supported patient as permanently high-stage merely because a device remains in place. Conversely, preserved pressure on escalating support cannot obscure worsening tissue perfusion. The classification should communicate a dynamic condition that prompts action rather than act as a retrospective administrative label.')],['SCAI2026','SCAICHECK','ACCSHOCK2025'],
 table=(['SCAI 2026 stage','Clinical distinction'],[
 ['A: at risk','Risk of shock without current instability or hypoperfusion'],
 ['B: beginning','Hemodynamic instability without hypoperfusion'],
 ['C: classic','Hypoperfusion requiring intervention beyond volume assessment/resuscitation'],
 ['D: deteriorating','Initial support fails to restore perfusion; persistent or worsening organ/perfusion abnormalities'],
 ['E: extremis','Acute or impending circulatory collapse; assess arrest-related neurological risk separately']]))

add('Cardiogenic shock','Assess Shock Response With Converging Perfusion Trends',
 'After initial treatment for cardiogenic shock, MAP rises from 54 to 72 mmHg. Over the next four hours lactate rises from 3.2 to 5.4 mmol/L, urine output remains low and the patient becomes more confused. Which assessment should guide the next action?',
 'Perfusion remains inadequate; urgently reassess the cause and adequacy of support using integrated serial findings',[
 ('Maintain current support and repeat lactate after another four hours','Repeat measurement is part of monitoring, but simultaneous worsening mentation and oliguria require action now. Waiting for the next scheduled sample can delay recognition that the pressure response has not restored adequate organ perfusion.'),
 ('Give a fluid challenge as the next intervention to improve lactate clearance','A cautious challenge can help selected patients with inadequate filling and plausible responsiveness. The supplied lactate and organ trends do not establish preload deficiency; ventricular loading and congestion should guide whether fluid is appropriate.'),
 ('Increase the vasopressor target MAP to 85 mmHg before changing other support','A higher individualized pressure target may help selected patients, but it is not the automatic treatment for rising lactate. More vasoconstriction can worsen afterload; flow, filling pressures and reversible causes require urgent reassessment.')],
 [S('Follow Organ Perfusion Alongside Pressure','**Blood pressure is one component of resuscitation, whereas its purpose is restoration of adequate organ perfusion.** Serial clinical and biochemical findings should converge before improvement is assumed.',
    'Track mental status, skin temperature and capillary refill, urine output, lactate, acid–base status, renal and hepatic function. Relate changes to treatment timing and the underlying disease.',
    'Lactate reflects the balance of production and clearance. Adrenergic stimulation, seizures or impaired hepatic clearance can contribute; a single concentration is neither a direct cardiac-output measurement nor a prescription for fluids.'),
  S('Identify Why Support Is Failing','**Reassess ventricular phenotype, congestion, oxygenation and reversible precipitants promptly.** Echocardiography and selected invasive measurements can distinguish insufficient output, excessive filling pressures or mixed vasodilation.',
    'Check drug delivery, arrhythmia, ischemia, mechanical complications, bleeding and infection as appropriate. Escalate through the shock team rather than waiting for a scheduled blood test when clinical deterioration is evident.',
    'Interpret creatinine and urine output in context because baseline kidney disease, obstruction and diuretic exposure can modify them. Conversely, do not dismiss simultaneous deterioration of several organs as a laboratory artifact. Use repeated observations to evaluate each intervention and reconsider support configuration or transfer when perfusion does not recover. Neither a normal numerical MAP nor one improving marker should override an otherwise worsening trajectory.')],['ACCSHOCK2025','SCAI2026'])

add('Cardiogenic shock','Use Invasive Hemodynamics When the Shock Phenotype Remains Uncertain',
 'A patient with cardiogenic shock remains hypoperfused despite initial treatment. Echocardiography shows biventricular dysfunction, but examination and imaging do not resolve whether persistent low output is driven predominantly by right-sided failure, left-sided congestion or accompanying vasodilation. An experienced shock team is available. Which investigation most directly guides physiological treatment selection?',
 'Pulmonary artery catheterization with integrated pressure and flow measurements',[
 ('Serial comprehensive bedside echocardiography','Echo remains important for function, valve lesions and device assessment. The stem specifies unresolved hemodynamic uncertainty after imaging; direct pressure and flow measurements can better separate the remaining congestion and vascular-tone mechanisms.'),
 ('Central venous pressure and central venous oxygen-saturation monitoring','These measurements help assess venous congestion and oxygen delivery, but do not directly provide left-sided filling pressure or a complete chamber-specific flow and resistance profile. They are useful complementary rather than equivalent data.'),
 ('Arterial pulse-contour cardiac-output monitoring','Pulse-contour systems can estimate output and trends in selected settings, with performance affected by calibration, vascular tone and rhythm. They do not directly measure pulmonary arterial and wedge pressures needed to clarify the supplied right-versus-left congestion question.')],
 [S('Measure the Variables That Change Management','**Selected invasive hemodynamics can resolve an uncertain shock phenotype and assess response to treatment.** Obtain right atrial, pulmonary arterial and pulmonary artery wedge pressures together with cardiac output and arterial pressure.',
    'Integrate these measurements to assess right- versus left-sided congestion, low forward flow and systemic or pulmonary vascular resistance. Mixed cardiogenic and vasodilatory shock may require a different strategy from isolated pump failure.',
    'A high right atrial pressure alone does not establish fluid responsiveness. Likewise, a low EF cannot indicate whether another fluid bolus, vasopressor, inotrope or chamber-specific support will improve perfusion.'),
  S('Interpret Carefully and Avoid Delaying Rescue','**A catheter supplies physiological information rather than treating shock by itself.** Use it when results can change treatment and a team can insert, interpret and act on the data safely.',
    'Confirm transducer leveling, waveforms and a credible wedge measurement; account for positive-pressure ventilation, valvular disease and factors affecting cardiac-output measurement. Reconcile unexpected values with echo and clinical findings.',
    'Bleeding, vascular injury, infection, arrhythmia and rare pulmonary artery injury are relevant procedural risks. Do not extrapolate a universal survival benefit from observational associations, and do not delay urgent resuscitation or definitive correction of a mechanical cause for catheter placement. Repeat hemodynamic assessment alongside organ-perfusion trends to determine whether the chosen intervention actually restores flow and relieves congestion.')],['ACCSHOCK2025','AHA2022'])

add('Cardiogenic shock','Recognize Combined Pump Failure and Vasodilation',
 'A patient with severe systolic HF and pneumonia develops hypoperfusion. Reliable invasive measurements show cardiac index 1.7 L/min/m², right atrial pressure 15 mmHg, wedge pressure 25 mmHg and systemic vascular resistance 650 dyn·s/cm⁵. Which phenotype best integrates these findings?',
 'Mixed cardiogenic and vasodilatory shock',[
 ('Predominantly isolated LV pump failure with compensatory vasoconstriction','Low output and elevated wedge pressure support LV failure, but the low systemic vascular resistance contradicts a purely compensatory vasoconstricted phenotype and identifies an additional vasodilatory component.'),
 ('Predominantly isolated RV failure with preserved left-sided filling pressure','Isolated RV failure can produce high right atrial pressure with relatively normal or low wedge pressure. The substantially elevated wedge pressure here indicates additional left-sided congestion.'),
 ('Predominantly distributive shock with preserved cardiac pumping','Infection can lower systemic resistance, but the measured low cardiac index and high filling pressures indicate important pump failure rather than preserved forward-flow capacity.')],
 [S('Integrate Flow, Filling Pressures and Vascular Tone','**Shock mechanisms can coexist.** Low cardiac index with elevated filling pressures indicates a congested low-output cardiac component; low systemic vascular resistance identifies accompanying vasodilation.',
    'Infection may precipitate both vasoplegia and worsening myocardial performance. Advanced cardiac shock can also acquire an inflammatory vasodilatory component; an infectious source still requires its own evaluation.',
    'Interpret catheter data with echo, examination, ventilation and treatment exposure. A phenotype describes physiology at the time of measurement, not an immutable diagnosis throughout the admission.'),
  S('Compare Chamber-Specific Patterns','**LV-predominant failure commonly raises wedge pressure, whereas RV-predominant failure disproportionately raises right atrial pressure.** Biventricular failure can raise both; vascular resistance must be assessed separately.',
    'These patterns are guides rather than rigid diagnostic thresholds. Valvular disease, pericardial constraint, positive-pressure ventilation and measurement error can alter the relationship between pressures and ventricular function.',
    'Treatment must support pressure and flow while addressing infection and congestion. Consider norepinephrine for inadequate vascular tone and select additional inotropic or mechanical support according to persistent low output and ventricular phenotype. Avoid assuming that infection requires unrestricted fluid administration in a patient with high filling pressures. Reassess perfusion and congestion after each change because increasing vasoconstriction alone can worsen ventricular afterload, while an inodilator alone can aggravate hypotension.')],['ACCSHOCK2025','AHA2022'])

R['SOAPII']=('SOAP II randomized comparison of dopamine and norepinephrine, 2010','https://doi.org/10.1056/NEJMoa0907118')
R['AHASHOCK2017']=('AHA scientific statement on contemporary cardiogenic shock management, 2017','https://doi.org/10.1161/CIR.0000000000000525')

add('Cardiogenic shock','Choose Norepinephrine for Hypotensive Cardiogenic Shock With Tachycardia',
 'A patient with cardiogenic shock has BP 72/44 mmHg, sinus tachycardia at 122/min and frequent ventricular ectopy. Initial assessment finds no fluid-responsive deficit. Which is the most appropriate initial vasopressor among the following?',
 'Norepinephrine infusion',[
 ('Dopamine infusion','Dopamine can increase pressure and rate, but its greater arrhythmia burden makes it less attractive with existing tachycardia and ventricular ectopy. Selected bradycardic presentations require a different assessment.'),
 ('Epinephrine infusion','Epinephrine can support pressure and contractility and is used in selected rescue settings. Tachycardia, arrhythmia, increased myocardial oxygen demand and adrenergic lactate production make it a less suitable initial choice here.'),
 ('Phenylephrine infusion','Pure alpha-mediated vasoconstriction can raise pressure but increases ventricular afterload without direct inotropic support. It may have selected uses when vasodilation and particular physiology dominate, but is less suitable for this low-output pump-failure presentation.')],
 [S('Support Pressure Without Unnecessary Chronotropic Burden','**Norepinephrine predominantly increases vascular tone through alpha-adrenergic activity with some beta-1 activity.** It is commonly preferred when cardiogenic shock requires a vasopressor, particularly with tachycardia or arrhythmia risk.',
    'The ACC 2025 guidance lists an infusion range of 0.05–1 microgram/kg/min. Titrate the lowest effective dose to individualized pressure and organ-perfusion goals using continuous monitoring; the range is not a mandatory starting dose for every patient.',
    'Pressure support alone may not correct low forward flow. Reassess cardiac output, filling pressures and organ function to determine whether an inotrope or mechanical strategy is also needed.'),
  S('Interpret Comparative Evidence and Monitor Harm','**SOAP II found no significant overall 28-day mortality difference between dopamine and norepinephrine across all shock types, but more arrhythmias occurred with dopamine.** Its cardiogenic-shock subgroup also showed an adverse mortality signal with dopamine.',
    'The subgroup finding should not be presented as a dedicated adequately powered cardiogenic-shock mortality trial. Clinical selection combines comparative safety evidence, physiological effects and the individual phenotype.',
    'Monitor rhythm, ischemia, lactate and peripheral perfusion. Excessive vasoconstriction can impair tissue flow and increase afterload; line extravasation can cause injury. Obtain appropriate vascular access and surveillance while avoiding delay in urgent pressure support under a monitored protocol. Continue cause-directed therapy and repeated assessment rather than treating achievement of a numerical pressure target as definitive shock reversal.')],['ACCSHOCK2025','SOAPII','AHASHOCK2017'])

add('Cardiogenic shock','Select an Inotrope With Renal Function and Titration in Mind',
 'A patient with low-output cardiogenic shock remains hypoperfused after norepinephrine restores MAP to 70 mmHg. Heart rate is 105/min. There is severe evolving oliguric AKI, no recent beta-blocker exposure and no dynamic LV outflow obstruction. Which additional infusion best provides rapidly titratable inotropy while limiting concern about renal drug accumulation?',
 'Dobutamine',[
 ('Milrinone','Milrinone is an effective inodilator in selected patients, including some with beta-blockade or pulmonary vascular disease. Renal elimination and a longer duration of effect make it less readily titratable in severe evolving AKI even when its dose is reduced.'),
 ('Epinephrine','Epinephrine can provide contractile and pressure support in selected rescue situations. Pressure is already supported here; additional chronotropic and metabolic effects make a separately titratable dobutamine strategy more appropriate than adding another inopressor.'),
 ('Dopamine','Dopamine can increase contractility and pressure and may be considered in selected bradycardic presentations. This patient is already tachycardic; its arrhythmia burden and less favorable comparative safety make it a poorer fit for targeted additional inotropy.')],
 [S('Match Pharmacology to the Immediate Problem','**Dobutamine provides predominantly beta-adrenergic inotropic support and is rapidly titratable.** Severe evolving AKI favors caution with renally cleared milrinone, whose effects can persist as clearance falls.',
    'The ACC 2025 guidance lists dobutamine at 2–10 micrograms/kg/min and milrinone at 0.125–0.5 microgram/kg/min. These are reference infusion ranges rather than universal starting prescriptions; select a low initial dose and titrate to response.',
    'Both agents can cause tachyarrhythmia and hypotension. Continue pressure support as needed and monitor ECG, arterial pressure, perfusion, congestion and renal trajectory. Inotropes are temporary physiological support, not a substitute for correcting the precipitant.'),
  S('Recognize Situations Favoring a Different Choice','**Milrinone inhibits phosphodiesterase-3 and acts independently of beta receptors.** Beta-blockade or a need for pulmonary vasodilation may influence selection when pressure and renal clearance permit.',
    'Dobutamine responses may be attenuated by beta-blockade; its chronotropic effects can be problematic with tachyarrhythmia or ischemia. Significant dynamic LV outflow obstruction requires a different physiological strategy because increased contractility can worsen obstruction.',
    'The supplied case favors dobutamine for practical pharmacokinetic reasons, not because it has proven universal survival superiority. Reassess whether output and organ perfusion actually improve at an acceptable rhythm and pressure cost. Persistent deterioration despite appropriate pharmacological support should trigger shock-team review of device support and the treatment destination rather than indefinite escalation of catecholamines.')],['ACCSHOCK2025','AHASHOCK2017'])

R['DOREMI']=('DOREMI randomized trial of milrinone versus dobutamine, 2021','https://doi.org/10.1056/NEJMoa2026845')
add('Cardiogenic shock','DOREMI Did Not Establish Superiority or Equivalence',
 'Which statement best interprets the randomized DOREMI trial comparing milrinone with dobutamine in cardiogenic shock?',
 'No significant difference in the primary composite was demonstrated; drug selection still depends on patient physiology',[
 ('Milrinone established superiority because its primary event rate was numerically lower','A numerical difference does not establish superiority when the confidence interval includes no effect and the prespecified statistical comparison is not significant.'),
 ('The two agents established equivalence because the primary comparison was not significant','Failure to show superiority does not demonstrate equivalence. That conclusion requires an appropriate equivalence design, prespecified margins and sufficiently precise results.'),
 ('Dobutamine established renal superiority because it does not depend on renal elimination','Pharmacokinetics can guide individual selection, especially with AKI, but does not convert the trial into proof of a superior renal clinical outcome for dobutamine.')],
 [S('Population and Primary Result','**DOREMI was a double-blind randomized trial involving 192 patients with cardiogenic shock.** It compared milrinone and dobutamine using a composite of major in-hospital clinical events.',
    'The primary outcome occurred in 49% with milrinone and 54% with dobutamine: relative risk 0.90, 95% CI 0.69–1.19; P=0.47. This did not demonstrate a significant treatment difference.',
    'The composite included death, resuscitated arrest, transplantation or mechanical circulatory support, nonfatal infarction, neurological ischemic events and initiation of renal replacement therapy. Do not describe the composite percentage as a mortality rate.'),
  S('Apply the Result Without Overinterpreting It','**The confidence interval permits clinically relevant benefit or harm and does not establish identical effects.** The single-center trial also cannot resolve every etiological, renal-function or treatment subgroup.',
    'Choose between agents using blood pressure, vascular resistance, rhythm, beta-blocker exposure, kidney function and the need for rapid dose adjustment. Milrinone can accumulate with renal dysfunction; dobutamine can increase rate and myocardial oxygen demand.',
    'Neither agent should be selected merely to reproduce the smaller numerical event rate. Monitor the actual physiological response and toxicity, and reassess escalation when pharmacological support fails. Post hoc subgroup analyses can suggest hypotheses but should not be promoted to definitive treatment rules without supporting evidence. A neutral comparison of two active therapies also does not demonstrate that routine inotropes improve outcomes in adequately perfused decompensated HF.')],['DOREMI','ACCSHOCK2025'],style='direct')

add('Cardiogenic shock','Contact the Regional Shock Center Before Rescue Options Are Exhausted',
 'At a hospital without cardiac surgery or temporary mechanical support, a patient with HF-related cardiogenic shock develops rising lactate and worsening renal function despite initial vasoactive treatment. Which organizational step should accompany immediate stabilization?',
 'Contact the regional advanced shock center now and coordinate specialist assessment and a supported transfer plan',[
 ('Complete a further six-hour local inotrope trial before contacting the regional team','A monitored trial may be reasonable when perfusion is improving and adequate capabilities exist. Here lactate and renal function are worsening, so delaying contact risks losing the window for supported transfer.'),
 ('Obtain cardiac MRI locally before discussing advanced-center referral','CMR can characterize myocardial disease after stabilization, but ongoing shock requires immediate physiological support and cause-directed evaluation. Tissue characterization should not delay coordination for unavailable rescue capabilities.'),
 ('Arrange transfer after routine transport becomes available the following morning','Routine transport may suit stable referrals. Progressive hypoperfusion requires urgent discussion of specialist retrieval, stabilization and destination rather than prespecifying a delay based on routine transport availability.')],
 [S('Activate a System of Care Early','**The ACC 2025 shock guidance recommends early contact with a regional advanced shock center when local expertise or capabilities are limited.** Contact and ongoing stabilization should proceed together.',
    'Communicate the suspected cause, shock trajectory, neurological status, ventricular phenotype, current support, oxygenation and evolving organ injury. State what definitive treatments are unavailable locally.',
    'A multidisciplinary team can assess recovery potential, intervention, temporary support, durable support or transplantation and the appropriate destination. Referral does not automatically commit the patient to a device.'),
  S('Make Transfer a Clinical Intervention','**Choose transport timing and support through direct discussion with the receiving and retrieval teams.** Assess whether current pressure, airway and circulation can be maintained during movement.',
    'Confirm acceptance, monitoring, vascular access, infusion supply, trained personnel and contingencies. An unstable patient may require specialist retrieval or stabilization before departure rather than routine transport.',
    'Continue investigation and treatment of reversible causes, including ischemia, arrhythmia, infection and mechanical complications. Do not postpone an immediately available lifesaving procedure simply to complete referral paperwork. Conversely, repeated local escalation without an achievable definitive strategy can waste the period when advanced treatment is feasible. Include the patient or surrogate in goals-of-care discussions as circumstances permit, and communicate uncertainty rather than promising that transfer or support will ensure survival.')],['ACCSHOCK2025'])

R['IABPSHOCKII']=('IABP-SHOCK II randomized trial, 2012','https://doi.org/10.1056/NEJMoa1208410')
R['ACS2025']=('ACC/AHA multisociety acute coronary syndromes guideline, 2025','https://doi.org/10.1161/CIR.0000000000001309')
add('Cardiogenic shock','Separate Routine IABP Use From Selected Bridging Indications',
 'Which conclusion from IABP-SHOCK II is most appropriate for an infarct-related cardiogenic shock patient undergoing early revascularization without a mechanical complication?',
 'Routine IABP did not reduce thirty-day mortality in the studied population',[
 ('Routine IABP reduced mortality because diastolic augmentation improves coronary perfusion','A physiological effect does not establish a survival benefit. The randomized trial did not demonstrate lower thirty-day mortality despite the rationale for diastolic augmentation and systolic unloading.'),
 ('Routine IABP reduced mortality only after excluding procedural bleeding events','The primary randomized mortality comparison was neutral. Excluding a treatment complication does not establish the claimed clinical benefit and would not preserve the intended overall benefit–harm comparison.'),
 ('IABP-SHOCK II established noninferiority of IABP to a microaxial pump','The comparator was care without routine IABP, not a randomized microaxial-pump strategy. The trial therefore cannot establish comparative device noninferiority or an appropriate noninferiority margin.')],
 [S('Know the Trial Population and Endpoint','**IABP-SHOCK II randomized 600 patients with acute infarction complicated by cardiogenic shock and planned early revascularization.** Routine balloon support did not significantly reduce thirty-day mortality.',
    'Mortality was 39.7% with IABP and 41.3% with control: relative risk 0.96, 95% CI 0.79–1.17; P=0.69. Do not convert a neutral result into proof of benefit from its physiological mechanism.',
    'The result argues against routine insertion solely because infarct-related shock is present. It does not replace urgent revascularization or identify the best support strategy for every shock phenotype.'),
  S('Understand Mechanism and Selected Exceptions','**The balloon inflates during diastole and deflates before systole, augmenting diastolic pressure and reducing systolic afterload.** Its circulatory assistance is limited compared with higher-flow pumps.',
    'Selected acute severe mitral regurgitation or ventricular septal rupture may warrant temporary support as a bridge to definitive treatment after multidisciplinary assessment. This is distinct from routine use in uncomplicated infarct-related shock and lacks the same randomized evidence base.',
    'Assess aortic pathology, regurgitation, vascular access and bleeding risk before insertion. Significant aortic regurgitation can worsen with diastolic inflation; aortic dissection is a major contraindication. Monitor limb perfusion, bleeding, platelet count and device timing. A bridge must have an explicit destination and repeated reassessment; modest pressure improvement cannot justify delaying necessary surgical or interventional correction of a mechanical lesion.')],['IABPSHOCKII','ACS2025','ACCSHOCK2025'],style='direct')

R['ECLSSHOCK']=('ECLS-SHOCK randomized trial, 2023','https://doi.org/10.1056/NEJMoa2307227')
R['DANGERSHOCK']=('DanGer-Shock randomized trial, 2024','https://doi.org/10.1056/NEJMoa2312572')
R['TMCS2026']=('EAPCI/ACVC consensus on temporary mechanical circulatory support, 2026','https://doi.org/10.1093/eurheartj/ehag708')

add('Cardiogenic shock','ECLS-SHOCK Does Not Support Routine Early VA-ECMO for Every Infarct-Related Shock',
 'Which statement best reflects ECLS-SHOCK when considering early extracorporeal support for infarct-related cardiogenic shock with planned revascularization?',
 'Routine early ECLS did not lower thirty-day mortality and increased important bleeding and vascular complications',[
 ('Routine early ECLS lowered mortality sufficiently to justify insertion in every eligible presentation','The trial did not demonstrate lower thirty-day mortality. Universal insertion also disregards important access, bleeding and physiological risks that increased with the intervention.'),
 ('Early ECLS reduced mortality but the benefit was offset by more vascular complications','The primary mortality comparison itself was neutral; the trial did not demonstrate a mortality benefit subsequently canceled by a separate safety endpoint. Bleeding and vascular events were additional harms.'),
 ('ECLS-SHOCK compared mandatory LV unloading plus ECMO with standard care','Routine mandatory LV unloading was not the tested treatment package. The study cannot establish the effect of a universal combined unloading strategy simply from its evaluation of early ECLS.')],
 [S('Interpret the Randomized Comparison','**ECLS-SHOCK tested early extracorporeal life support in acute infarction complicated by shock with planned early revascularization.** Thirty-day mortality was not significantly lower with ECLS.',
    'Death occurred in 47.8% versus 49.0%: relative risk 0.98, 95% CI 0.80–1.19; P=0.81. This is a neutral superiority comparison rather than proof of identical outcomes in every subgroup.',
    'Moderate or severe bleeding occurred in 23.4% versus 9.6%; peripheral vascular complications requiring intervention occurred in 11.0% versus 3.8%. These harms matter when selecting patients.'),
  S('Choose Support From the Clinical Problem','**VA-ECMO provides systemic circulatory support and gas exchange but introduces additional loading, vascular and anticoagulation considerations.** Its capabilities differ from isolated LV or RV pumps.',
    'Assess neurological prognosis, reversible cause, ventricular phenotype, oxygenation, access feasibility and an achievable destination. A device should not be inserted solely because a patient meets a broad shock label.',
    'Monitor limb perfusion, bleeding, hemolysis, gas exchange and ventricular distention after initiation. Peripheral return may increase LV afterload; absent aortic valve opening or pulmonary edema should prompt unloading assessment. The trial does not establish that a microaxial pump is superior to ECMO because the devices were not directly randomized against each other. Continue cause-directed treatment and reassess whether support is enabling recovery or another viable bridge.')],['ECLSSHOCK','ACCSHOCK2025','TMCS2026'],style='direct')

add('Cardiogenic shock','Apply DanGer-Shock to Its Selected STEMI Population',
 'A conscious patient has STEMI-related shock of six hours duration, LVEF 25%, lactate 4.0 mmol/L and a vasopressor requirement. There is no overt RV failure, mechanical complication or device contraindication. Which statement most accurately supports discussion of a microaxial flow pump?',
 'DanGer-Shock demonstrated lower one-hundred-eighty-day mortality in a selected similar population, with increased device-related complications',[
 ('DanGer-Shock directly compared a microaxial pump with VA-ECMO and found better survival','The randomized comparator was standard care, not a VA-ECMO strategy. Differences between DanGer-Shock and ECLS-SHOCK cannot substitute for a head-to-head device comparison because populations and endpoints also differed.'),
 ('DanGer-Shock showed a mortality benefit without an important increase in complications','The survival result came with substantially increased safety events and renal replacement therapy. Omitting these harms misrepresents the treatment trade-off.'),
 ('DanGer-Shock established pre-PCI insertion as superior to post-PCI insertion','Randomization and insertion timing varied, but timing was not the randomized comparison. The study therefore does not prove superiority of one insertion sequence, and device planning must not unnecessarily delay reperfusion.')],
 [S('Identify Who Was Studied','**DanGer-Shock compared Impella CP plus standard care with standard care in selected STEMI-related cardiogenic shock.** Key features included hypotension or vasopressor need, hypoperfusion and LVEF below 45%.',
    'The commonly cited arterial lactate criterion was at least 2.5 mmol/L. Patients with overt RV failure or persistent coma after out-of-hospital arrest were excluded; do not extrapolate the result automatically to these presentations.',
    'In the 355-patient analysis, death by 180 days occurred in 45.8% versus 58.5%: hazard ratio 0.74, 95% CI 0.55–0.99; P=0.04. This endpoint differs from the thirty-day endpoint of ECLS-SHOCK.'),
  S('Balance Benefit Against Harm and Feasibility','**A composite safety event occurred in 24.0% with the pump versus 6.2% with standard care.** Bleeding, limb ischemia, hemolysis and other device-related complications require explicit consideration.',
    'Renal replacement therapy was also more frequent with the pump. Assess vascular access, aortic valve and LV anatomy, anticoagulation feasibility and the ability to monitor and manage complications.',
    'The 2025 ACS guideline supports consideration in patients resembling the trial population; it does not recommend indiscriminate use across all cardiogenic shock. The physiological need, neurological outlook, experienced team and a plausible bridge destination remain essential. A favorable mortality result does not make placement risk-free or prove superiority over every alternative device. Continue urgent revascularization and reassess hemodynamics, organ perfusion and device necessity throughout treatment.')],['DANGERSHOCK','ACS2025','TMCS2026'])

R['AHATMCS2022']=('AHA scientific statement on escalating and de-escalating temporary support, 2022','https://doi.org/10.1161/CIR.0000000000001076')
add('Cardiogenic shock','Match Temporary Support to the Failing Chamber',
 'A patient has refractory shock from severe isolated RV failure despite initial treatment. LV systolic function is preserved, wedge pressure is 9 mmHg, right atrial pressure is 22 mmHg and oxygenation is adequate. Which support strategy most directly addresses this physiology?',
 'Temporary right atrial-to-pulmonary arterial support',[
 ('Transaortic LV microaxial pump','An LV pump unloads and supports the left ventricle but depends on adequate delivery from the right heart. It does not directly bypass the severely failing RV in this isolated phenotype.'),
 ('Intra-aortic balloon counterpulsation','Counterpulsation changes aortic pressure and LV afterload and can support selected left-sided problems. It does not provide the direct venous-to-pulmonary arterial flow required to bypass this severely failing RV.'),
 ('Peripheral VA-ECMO','VA-ECMO can be appropriate with collapse, combined failure or gas-exchange problems. Here adequate oxygenation and preserved LV function favor assessment of chamber-specific support without the additional arterial-access and LV-afterload consequences of ECMO.')],
 [S('Support the Circulation That Is Failing','**Temporary RV assist devices bypass or augment the right heart by returning systemic venous blood to the pulmonary circulation.** Selection requires assessment of pulmonary vascular load, LV capacity and access feasibility.',
    'Preserved LV function and adequate oxygenation make a chamber-specific approach worth considering. Severe pulmonary vascular obstruction, concomitant LV failure or gas-exchange failure can change the required configuration.',
    'Use echo and hemodynamics to distinguish isolated RV failure from biventricular shock. Increasing pulmonary flow into a failing left ventricle may raise wedge pressure and worsen pulmonary edema.'),
  S('Check Device-Specific Risks and Contraindications','**No support device is interchangeable with another merely because both increase systemic perfusion.** Compare supported chamber, flow, oxygenation capability, access, anticoagulation and loading effects.',
    'Before a transaortic LV pump, assess for LV thrombus, a mechanical aortic valve, relevant aortic disease and access limitations. RV devices have their own anatomical and procedural restrictions; check the selected device instructions.',
    'Monitor position, flow, hemolysis, bleeding, limb or venous access complications and organ perfusion. Reconsider configuration when the phenotype changes rather than escalating pump speed without understanding the cause of poor flow. Device choice is a specialist team decision linked to recovery or another viable destination, not a substitute for treating the underlying RV insult or correcting a reversible obstruction.')],['AHATMCS2022','TMCS2026','ACCSHOCK2025'])

add('Cardiogenic shock','Recognize LV Distention During Peripheral VA-ECMO',
 'After peripheral VA-ECMO initiation, systemic pressure improves but pulmonary edema worsens. Echo shows progressive LV dilation and infrequent aortic valve opening. What is the most appropriate interpretation and next step?',
 'Suspect inadequate LV ejection against increased afterload and urgently assess a tailored LV unloading strategy',[
 ('Increase ECMO flow to improve systemic oxygen delivery','Increasing flow can help inadequate systemic support, but peripheral arterial return can also increase LV afterload. The supplied progressive LV distention and poor valve opening require unloading assessment rather than an isolated flow increase.'),
 ('Increase ventilator PEEP as the principal correction','PEEP can improve oxygenation in pulmonary edema and may be part of respiratory management. It does not directly resolve inadequate LV ejection and can alter venous return, so it cannot replace assessment of the underlying loading problem.'),
 ('Exchange the oxygenator to improve extracorporeal gas transfer','Oxygenator exchange is appropriate with demonstrated circuit gas-transfer failure or relevant thrombosis. Progressive LV dilation and infrequent valve opening instead point to ventricular loading and stasis; oxygenator exchange does not correct that mechanism.')],
 [S('Understand the Loading Problem','**Peripheral VA-ECMO arterial return can increase LV afterload.** A severely impaired ventricle may not eject adequately, leading to LV distention, increased filling pressure and pulmonary edema.',
    'Infrequent or absent aortic valve opening and reduced pulsatility are warning findings. Stasis can promote intracardiac or aortic-root thrombosis; evaluate the entire clinical and echocardiographic pattern.',
    'Assess device flow, arterial pressure, volume status, native ventricular function and valvular regurgitation. Distinguish pulmonary congestion from other causes of hypoxemia, including differential upper-body hypoxemia.'),
  S('Relieve Distention While Preserving Perfusion','**Urgently involve the ECMO and shock teams to individualize unloading.** Options can include adjustment of loading conditions and support settings, an LV pump, IABP or catheter/surgical venting according to anatomy and severity.',
    'Avoid indiscriminate flow reduction if systemic perfusion depends on current support. Equally, simply increasing ECMO flow can aggravate the loading problem; use echo and hemodynamics to assess the response.',
    'This symptomatic distention scenario differs from a claim that every patient benefits from routine prophylactic unloading with one device. Additional access and pumps increase bleeding, vascular and hemolysis risks. Select an intervention that addresses the actual problem, reassess valve opening and pulmonary congestion, and continue monitoring systemic organ perfusion. No single imaging observation alone determines readiness for ECMO withdrawal.')],['AHATMCS2022','ACCSHOCK2025','TMCS2026'])

add('Cardiogenic shock','Define and Reassess the Destination of Temporary Support',
 'A patient on temporary circulatory support has improving lactate and renal function but uncertain myocardial recovery. Neurological assessment and durable-therapy eligibility are still being clarified. Which strategy is most appropriate?',
 'Maintain a bridge-to-decision strategy while completing prognosis and candidacy assessment',[
 ('Define the current strategy as bridge to transplantation','Bridge to transplantation requires an established transplant pathway. Improved perfusion permits evaluation, but unresolved neurological status and candidacy mean transplantation cannot yet be assumed as the destination.'),
 ('Define the current strategy as bridge to recovery','Bridge to recovery is appropriate when native myocardial recovery is the selected feasible endpoint. Recovery remains uncertain here and other destinations are being evaluated, making bridge to decision the more accurate present strategy.'),
 ('Convert to a durable LVAD as the next planned step','Durable support can be appropriate when recovery is insufficient and eligibility is established. Neurological prognosis and durable-therapy candidacy remain unresolved, so an automatic conversion plan is premature.')],
 [S('Make the Bridge Explicit','**Bridge to decision provides time to clarify prognosis and treatment options while perfusion is supported.** It should lead to a defined decision rather than indefinite continuation without objectives.',
    'Bridge to recovery aims for device removal after sufficient native cardiac recovery. Bridge to durable support or transplantation requires assessment of eligibility and a realistic pathway to the intended therapy.',
    'A patient can move between bridge categories as information emerges. Communicate uncertainty and reassessment milestones with the patient or surrogate and the multidisciplinary team.'),
  S('Evaluate Native Function and Treatment Burden','**Reassess hemodynamics, echo, end-organ trends, neurological status and complications repeatedly.** Supported stability must be distinguished from the ability to maintain perfusion without the device.',
    'When recovery is plausible, perform a supervised device-specific weaning assessment with adequate pressure, flow and organ-perfusion monitoring. No single lactate, EF or pump-flow value universally proves readiness.',
    'If recovery is insufficient, evaluate durable LVAD or transplantation before irreversible organ injury develops. Consider RV function, comorbidity, infection, bleeding and psychosocial requirements in that assessment. If no viable recovery or advanced-therapy pathway exists, revisit the burdens and goals of ongoing support with specialist palliative care involvement. Such discussions accompany active treatment and should reflect prognosis and informed patient values rather than an arbitrary elapsed duration.')],['AHATMCS2022','ACCSHOCK2025'])

if __name__=='__main__':
    # Highlight selected teaching thresholds only; question options remain plain text.
    highlights={1:['below 50%','at least 50%'],5:['PAWP ≥15 mmHg','LVEDP ≥16 mmHg','PAWP ≥25 mmHg'],
      10:['at least 36 hours'],11:['24/26 mg twice daily','97/103 mg twice daily'],
      12:['12.5–25 mg once daily','200 mg once daily','1.25 mg once daily','10 mg once daily','3.125 mg twice daily'],
      13:['eGFR >30 mL/min/1.73 m²','potassium <5.0 mmol/L','below 5.5 mmol/L'],
      14:['10 mg once daily','eGFR 25 mL/min/1.73 m²','at least three days'],
      16:['more than 30% within four weeks'],23:['0.5 to <0.9 ng/mL','at least six hours'],
      26:['1000 mg initially and 500 mg at week six'],43:['rate >25/min','SpO2 <90%'],
      44:['160 mg IV per day'],45:['<50 mmol/L at two hours','2.5–5 mg'],
      46:['500 mg IV once daily'],47:['5 micrograms/min'],56:['0.05–1 microgram/kg/min'],
      57:['2–10 micrograms/kg/min','0.125–0.5 microgram/kg/min']}
    for number,phrases in highlights.items():
        for _,bullets in rows[number-1]['sections']:
            for index,(body,children) in enumerate(bullets):
                def marked(text):
                    for phrase in phrases:text=text.replace(phrase,'=='+phrase+'==')
                    return text
                bullets[index]=(marked(body),[marked(child) for child in children])
    cp=ROOT/'Cardiology'/(DOC+'.coverage.json');c=json.loads(cp.read_text(encoding='utf-8'))
    decisions=[(s['section'],d) for s in c['sections'] for d in s['decisions']]
    assert len(rows)<=len(decisions)
    for r,(topic,d) in zip(rows,decisions):
        assert r['topic']==topic
        r['coverageDecision']=d
    p=save('Cardiology',4,DOC,rows,R,'Original educational synthesis checked against named primary guidelines, prescribing information and trials. Guideline-specific terminology and jurisdiction-specific doses are identified. Full Harrison text not accessed; independent clinician review not claimed.')
    b=json.loads(p.read_text(encoding='utf-8'));b.update(status='chapter_authored',plannedQuestions=c['plannedQuestions']);p.write_text(json.dumps(b,ensure_ascii=False,indent=2),encoding='utf-8')
    assert len(rows)==len(decisions)==c['plannedQuestions']
    c.update(status='coverage_reviewed',authoredQuestions=len(rows),questionDecisions=[dict(question=i,title=r['title'],decision=r['coverageDecision'],section=r['topic']) for i,r in enumerate(rows,1)])
    cp.write_text(json.dumps(c,ensure_ascii=False,indent=2),encoding='utf-8')
    pp=ROOT/'progress.json';plan=json.loads(pp.read_text(encoding='utf-8'));entry=next(x for x in plan['chapters'] if x['subject']=='Cardiology' and x['document']==DOC)
    entry.update(status='authored_validated',authoredQuestions=len(rows),plannedQuestions=c['plannedQuestions']);pp.write_text(json.dumps(plan,ensure_ascii=False,indent=2),encoding='utf-8')
